(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["ro"] = {"ui":{"skip":"Sari la conținut","back":"← Înapoi la AI-gile","lang.button":"Limba: {name}","lang.dialog":"Alege o limbă","lang.search":"Caută limbi","lang.none":"Nicio limbă nu se potrivește","lang.notYet":"{name} nu e tradusă încă","theme.aria":"Schimbă tema: luminoasă, întunecată sau neagră","theme.toLight":"Treci la tema luminoasă","theme.toDark":"Treci la tema întunecată","theme.toBlack":"Treci la tema neagră (negru adevărat, blândă cu ecranele OLED)","words.underline":"Subliniază aceste cuvinte în pagină","words.underlineHelp":"Treci cu mouse-ul peste un cuvânt punctat sau atinge-l ca să vezi ce înseamnă.","words.col.todo":"Cardurile alese pentru acum: echipa începe cu ele în continuare.","words.col.doing":"Un AI lucrează chiar acum la acest card.","words.col.review":"Un AI a terminat treaba; altul o verifică înainte să ajungă la tine.","words.col.verify":"Te așteaptă pe tine: încearcă și spune dacă merge.","words.col.team":"Notițele sau răspunsurile tale, care așteaptă să le preia echipa.","words.col.done":"Terminat și acceptat.","index.title":"AI-gile: echipa ta de dezvoltare AI, pe o singură tablă","index.description":"AI-gile este o tablă kanban pentru echipe de programare cu AI. Ele lucrează cât dormi; tu primești o grămadă mică de lucruri de decis, de testat și de acceptat.","hero.logoAlt":"Pictograma tablei AI-gile","hero.h1.html":"Echipa ta de dezvoltare AI, pe o singură&nbsp;tablă.","hero.alpha":"🐣 Pre-alfa închis","hero.alphaTitle":"Început și neterminat: mulțumim că îl încerci!","hero.lede":"Ele construiesc cât dormi. Tu te trezești cu o grămadă mică: câteva întrebări, câteva lucruri de testat, un diamant mov sau două. Un clic, accepți, și te întorci la cafea.","dl.windows":"Aplicație pentru Windows","dl.browser":"Rulează-l în browser","dl.messenger":"📱 Messenger pentru telefonul tău","dl.soon":"În curând","dl.notify":"🔔 Anunță-mă când se deschide","dl.notifySmall":"Alfa sau beta","hero.secondary":"Agile, dar echipa nu are nevoie de cafeaua de la stand-up. (Fac stand-up oricum.)","pitch.h2":"AI-gile în câte cuvinte vrei","pitch.lede":"Alege o lungime, de la un cuvânt la 144. Fiecare lungime e o descriere aparte, scrisă pentru mărimea ei. Trage de cursor sau folosește săgețile.","pitch.rangeLabel":"Lungimea în cuvinte","pitch.dice":"🎲 altă versiune","pitch.words.one":"{n} cuvânt","pitch.words.other":"{n} de cuvinte","pitch.letters.one":"{n} literă","pitch.letters.other":"{n} de litere","pitch.chars.one":"{n} caracter","pitch.chars.other":"{n} de caractere","count.line.html.one":"{n} card pe tablă chiar acum","count.line.html.other":"{n} de carduri pe tablă chiar acum","people.humans.html.one":"👥 {n} om","people.humans.html.other":"👥 {n} de oameni","people.agents.html.one":"🤖 {n} agent","people.agents.html.other":"🤖 {n} de agenți","people.working.html.one":"⚡ {n} la treabă chiar acum","people.working.html.other":"⚡ {n} la treabă chiar acum","pre.title":"AI-gile: aici se construiește ceva","pre.description":"Aici se construiește ceva: o tablă pe care echipe AI construiesc ce le ceri și te învață pe parcurs. Deocamdată pre-alfa închis, cu prieteni.","pre.h1":"Aici se construiește ceva. 🤫","pre.line":"O tablă pe care echipe AI construiesc ce le ceri și te învață pe parcurs. Deocamdată pre-alfa închis, cu prieteni.","pre.btn":"🔔 Anunță-mă când se deschide","pre.peek":"În spatele sticlei: tabla adevărată, în direct. Fiecare card e o bară colorată.","pre.peekFake":"În spatele sticlei: așa arată o tablă la lucru.","pre.night":"🌙 Paznicul de noapte e la comandă · 😴 omul se odihnește","features.aria":"Ce face","f.pile.h":"O singură grămadă pentru tine","f.pile.html":"<b>Pentru tine</b> adună tot ce te așteaptă, din toate proiectele: întrebări, lucruri de testat, sarcini pe care le poate face doar un om. Coada ta spune ce urmează și cât durează.","f.sleep.h":"Echipe care lucrează cât dormi","f.sleep.p":"Fiecare proiect are un lider și o echipă de agenți AI. Lași un comentariu la un card, echipa se trezește, face treaba și ți-l dă înapoi cu pași pe care îi poate urma și un om obosit.","f.tester.h":"Un tester AI verifică primul","f.tester.p":"Înainte să ajungă la tine, un tester urmează pașii într-o copie a aplicației și arată ce a văzut, cu o captură de ecran. Răsfoiești rapid ce a trecut și accepți dintr-un clic.","f.proof.h":"Dovezi, nu promisiuni","f.proof.p":"Fiecare predare arată ce s-a schimbat: fișierele, diferențele, capturile de ecran. Nu mai deschizi fiecare aplicație ca să afli dacă e gata.","f.chat.h":"Vorbește cu liderii tăi","f.chat.p":"O bară în stil Discord: o pictogramă pentru fiecare proiect, diamante mov pentru ce are nevoie de tine. Trimite unui lider o idee; o transformă în carduri și într-un plan, cu un buton ✅ Go.","f.tidy.h":"Se ține singură în ordine","f.tidy.p":"Cardurile înrudite se unesc într-unul, titlurile încurcate se repară, iar o verificare a tokenilor ține codul suplu. Mai puține lucruri între care să sari, mai puține de gândit.","f.private.h":"A ta, pe calculatorul tău","f.private.li1":"Tabla rulează pe calculatorul tău și răspunde numai ție.","f.private.li2":"Mesajele private dintre oameni sunt criptate de la un capăt la altul.","f.private.li3":"Fără conturi, fără urmăritoare, fără cookie-uri.","f.lang.h":"În limba ta","f.lang.p":"Peste 120 de limbi, de la neerlandeză, galeză și japoneză până la limba piraților, a lui Yoda și klingoniană, cu o trecere rapidă înapoi la engleză pentru termenii de specialitate.","f.service.h":"De la o idee la un serviciu adevărat","f.service.p":"Ai construit cu AI ceva ce oamenii folosesc acum? Marchează-l ca serviciu și panoul te ajută să-l rulezi bine: verificări de disponibilitate, o pagină de status publică, incidente cu o analiză scrisă, modificări care au nevoie de un Go, backupuri verificate zilnic. Ajutorul te învață fiecare pas pe drum.","msgr.h2":"AI-gile Messenger: echipa ta în buzunar","msgr.p1":"Vorbește cu echipa ta AI fără să deschizi board-ul. Scrie-le pe chat liderilor de proiect și prietenilor, vezi pașii de test ai unui card și răspunde-le, totul de pe telefon.","msgr.p2":"Ca să-l asociezi, scanează un cod QR de pe board-ul tău. Prima dată? Un chat demo prietenos îți arată tot.","msgr.when":"Întâi pe Android, apoi o versiune web pentru telefoane și iPhone.","msgr.who":"Liderul proiectului tău","msgr.b1":"Remedierea pentru modul întunecat e gata. Vrei pașii de test?","msgr.b2":"Da, te rog!","msgr.b3":"1. Deschide Setări. 2. Alege Întunecat. Arată bine?","tl.aria":"Cronologie de la prima discuție până la foaia de parcurs","tl.h2":"De la prima discuție la ce urmează","tl.lede":"Date și ore reale, în fusul tău orar. După azi e planul, fără date promise.","tl.today":"Azi","tl.planned":"planificat","tl.doing":"în lucru","tl.cards.one":"{n} card","tl.cards.other":"{n} de carduri","join.h2":"Vino și tu","join.lede":"AI-gile e construit de un ciudat bărbos cu AuDHD și câteva lupte cu sănătatea mintală, și de o mulțime de agenți răbdători. Deocamdată e privat, într-un alfa închis, cu prieteni. Vrei să-l încerci când se deschide?","join.btn":"Spune-mi că ești interesat","join.small":"Îți scriem pe e-mail, nimic altceva","footer.tag":"AI-gile. Fără urmăritoare, fără cookie-uri, fără cafea de stand-up.","footer.licence":"Licență pentru firme","footer.status":"Stare","footer.privacy":"Ce păstrăm","footer.thanks":"Apeluri mulțumită ChilledChat","form.sending":"Se trimite…","form.failed":"N-a mers: mai încearcă mai târziu.","form.offline":"Nu am ajuns la AI-gile: mai încearcă mai târziu.","form.keep":"Folosim asta doar ca să-ți răspundem, apoi o ștergem. Fără urmăritoare, fără cookie-uri.","form.keepLink":"Ce păstrăm","interest.title":"AI-gile: anunță-mă când se deschide alfa","interest.description":"Lasă-ți e-mailul ca să afli când se deschide alfa sau beta închisă a AI-gile.","interest.h1":"🔔 Anunță-mă când se deschide","interest.lede":"AI-gile e în pre-alfa închis. Lasă-ți e-mailul și îți scriem o singură dată, când e loc și pentru tine.","interest.email":"E-mailul tău","interest.which":"Ce test?","interest.alpha":"Alfa închis: timpuriu, aspru, cu multe schimbări","interest.beta":"Beta: mai stabil, mai târziu","interest.both":"Oricare, care vine mai întâi","interest.submit":"Pune-mă pe listă","interest.thanks":"Mulțumim! Ești pe listă.","licence.title":"AI-gile: licență pentru firme","licence.description":"Folosești AI-gile în firma ta? Cere o licență gratuită pentru firme.","licence.h1":"📜 Licență pentru firme","licence.lede":"Folosești AI-gile la serviciu? Spune-ne cine ești și ce faci. Dacă face puțin bine, licența e gratuită.","licence.company":"Firma","licence.website":"Site web","licence.what":"Ce faci","licence.how":"Cum ajută lumea","licence.email":"E-mail","licence.submit":"Trimite cererea","licence.thanks":"Mulțumim! Îți răspundem pe e-mail.","status.title":"Starea AI-gile","status.h1":"Starea AI-gile","status.quiet":"Totul e liniștit","status.intro":"Funcționează AI-gile chiar acum? Pagina asta verifică site-ul, partajarea tablelor, apelurile și descărcarea la fiecare 5 minute.","status.up":"Funcționează (a răspuns în {ms} ms)","status.slow":"N-a răspuns la ultima verificare, reîncerc","status.down":"Nu funcționează: n-a răspuns la ultimele două verificări","status.svc.web":"Site","status.svc.web.offers":"Site-ul ăsta: ce e AI-gile și formularul de interes","status.svc.boards":"Partajarea tablelor","status.svc.boards.offers":"Table publice, mesaje între prieteni și invitații","status.svc.calls":"Apeluri","status.svc.calls.offers":"Voce, video și partajarea ecranului în AI-gile","status.svc.download":"Descărcare","status.svc.download.offers":"Programul de instalare pentru Windows și linkurile de invitație","status.checking":"Se verifică…","status.offline":"Nu pot contacta serviciul de stare acum (reîncerc)","status.updated":"actualizat {ago}","status.justNow":"chiar acum","status.min":"acum {n} min","status.hours":"acum {n} h","status.days":"acum {n} z","privacy.title":"AI-gile: ce păstrăm","privacy.h1":"Ce păstrăm","privacy.lede":"Pe scurt: doar ce ne trimiți tu, și nu pentru mult timp.","privacy.only":"Doar ce ne trimiți: ce scrii într-un formular, cum ar fi e-mailul tău. Nimic altceva despre tine.","privacy.sealed":"E sigilat, ca serverul nostru să nu-l poată citi: în browserul tău, înainte să plece (într-un browser mai vechi, în clipa în care ajunge). Doar tabla noastră îl poate deschide.","privacy.server":"E șters de pe server imediat ce ajunge pe tabla noastră. Orice a rămas acolo după 30 de zile e șters oricum.","privacy.board":"Îl păstrăm pe tabla noastră doar până îți răspundem, apoi îl ștergem și de acolo.","privacy.none":"Fără urmăritoare, fără cookie-uri, fără statistici.","privacy.local":"Limba ta și alegerea temei luminoase sau întunecate rămân în browserul tău. Nu ne sunt trimise niciodată.","privacy.ask":"Vrei să dispară mai devreme? Răspunde la e-mailul nostru și spune-ne.","live.h2":"Privește-l cum se construiește, în direct","live.caption":"Fiecare card este ascuns: vezi forma muncii, nu cuvintele.","live.watching.one":"în direct: {n} privește","live.watching.other":"în direct: {n} privesc","live.last.now":"Ultimul card a fost mutat chiar acum","live.last.min.one":"Ultimul card a fost mutat acum {n} min","live.last.min.other":"Ultimul card a fost mutat acum {n} min","live.last.hour.one":"Ultimul card a fost mutat acum {n} oră","live.last.hour.other":"Ultimul card a fost mutat acum {n} ore","live.last.day.one":"Ultimul card a fost mutat acum {n} zi","live.last.day.other":"Ultimul card a fost mutat acum {n} zile","live.offline":"Tabloul live ia o mică pauză. Revino în curând.","live.cols":"Backlog|De făcut|În lucru|Echipa verifică|Așteaptă testul tău|Pentru echipă|Gata","pitch.words.few":"{n} cuvinte","pitch.letters.few":"{n} litere","pitch.chars.few":"{n} caractere","count.line.html.few":"{n} carduri pe tablă chiar acum","tl.cards.few":"{n} carduri","footer.models":"AI-gile rulează modele AI pentru tine. Ce spun și ce fac ele țin de ele, așa că verifică înainte să te bazezi pe ele.","privacy.ai.h":"Partea cu AI","privacy.ai.models":"AI-gile este board-ul. Munca o fac modele AI de la alte companii, precum Claude, Codex și Gemini, pe conturile tale.","privacy.ai.check":"Ce scriu și ce fac vine de la ele și poate fi greșit. Verifică înainte să te bazezi pe asta sau să publici.","privacy.ai.files":"Ele modifică fișiere și rulează comenzi în folderele pe care le conectezi. Fă o copie de rezervă.","privacy.ai.send":"Ce dai unui model ajunge la compania care îl rulează, conform termenilor ei. Se aplică termenii și costurile fiecăruia.","privacy.ai.asis":"AI-gile este o versiune de test timpurie, oferită așa cum este."},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Roboți.","Delegat."]},{"n":2,"texts":["Kanban robotic.","Agenți, organizați.","Idei, construite."]},{"n":3,"texts":["Kanban pentru roboți.","Ideile devin funcții.","Kanban gratuit pentru agenți."]},{"n":5,"texts":["O tablă kanban condusă de agenți.","Tu scrii carduri. Agenții construiesc.","Gratuit, local, testat, puțin caraghios."]},{"n":8,"texts":["O tablă kanban gratuită unde lucrează agenți AI.","Scrii o idee. Agenții o construiesc. Tu accepți.","Agile pentru un om și mulți roboți răbdători."]},{"n":13,"texts":["O tablă kanban pe calculatorul tău, unde agenți AI preiau cardurile.","Scrii o idee. O echipă de agenți o construiește. Un tester o verifică.","Gratuit, fără conturi, fără urmăritoare: o tablă, niște roboți și tu la comandă."]},{"n":21,"texts":["AI-gile este o tablă kanban pentru lucrul cu agenți AI de programare. Ei preiau cardurile; tu le testezi și le accepți.","Fiecare proiect primește un lider și o echipă de agenți AI. Lași un comentariu la orice card și echipa se pune pe treabă.","O listă personală de sarcini, gratuită, care rulează pe calculatorul tău. Muncitorii sunt roboți. Cel care spune da ești tu."]},{"n":34,"texts":["Pui ideile pe o tablă. O echipă de agenți AI le face funcții care merg, le testează și ți le dă înapoi cu pași de încercat. Nimic nu e gata până nu spui tu că e gata.","AI-gile este o tablă kanban făcută în casă, pe care Rich a construit-o cu mult ajutor de la agenții pe care acum îi coordonează. E gratuită, rulează pe calculatorul tău și se dă prietenilor, nu se vinde.","Imaginează-ți o tablă kanban obișnuită, cu coloane de la Backlog până la Gata, doar că cardurile sunt preluate de agenți AI. Ei raportează cum merge, întreabă când se blochează și așteaptă mereu încuviințarea ta."]},{"n":55,"texts":["AI-gile este o tablă kanban în care echipa e făcută din agenți AI. Fiecare proiect are un lider care planifică munca și ajutoare care o construiesc. Când o funcție e gata, un tester AI o încearcă și face o captură de ecran, apoi ajunge în grămada ta. O accepți sau lași un comentariu și o refac.","A început ca felul în care un singur om ținea evidența multor sesiuni de programare cu AI deodată și a crescut într-o tablă adevărată. Rulează pe calculatorul tău, nu cere cont și n-are urmăritoare. E gratuită pentru prieteni și pentru oricine e curios. E și neterminată, așa că așteaptă-te la colțuri aspre și la câte o surpriză.","Iată varianta cinstită. Ideile tot tu trebuie să le ai, iar rezultatele tot tu trebuie să le verifici. Ce face AI-gile este tot ce e între ele: ține cardurile în ordine, trezește agentul potrivit când comentezi, arată exact ce s-a schimbat și strânge totul într-o singură grămadă scurtă pentru tine."]},{"n":89,"texts":["AI-gile este o tablă kanban gratuită pe care o rulezi pe propriul calculator. În loc de oameni, fiecare proiect are o echipă de agenți AI: un lider care transformă ideile tale în carduri și într-un plan, și ajutoare care iau cardurile în ordinea priorității. Când ceva e construit, un tester AI urmează pașii de test și îți arată ce a văzut. Apoi așteaptă într-o singură grămadă numită Pentru tine. O accepți sau lași un comentariu și echipa mai încearcă o dată. Nimic nu ajunge vreodată la Gata fără tine.","Câteva lucruri la care poate nu te aștepți. O veghe de noapte ține coloana De făcut plină cât dormi, alegând carduri care nu cer niciun răspuns de la tine. Un contor de tokeni arată cât au folosit agenții azi și săptămâna asta, iar Modul fără tokeni le spune să nu mai cheltuiască. Poți scrie prietenilor, iar mesajele private sunt criptate de la un capăt la altul. Tabla vorbește vreo 120 de limbi, printre ele neerlandeza, flamanda, limba piraților și klingoniana. Nimic din toate astea nu costă un ban și nimeni nu încearcă să ți le vândă.","AI-gile este un proiect mic, personal, nu o companie. Rich voia să țină sub ochi mai multe proiecte de programare cu AI fără să deschidă fiecare aplicație, așa că el și agenții au făcut o tablă pentru asta, apoi au folosit tabla ca să construiască restul. E în pre-alfa închis, ceea ce înseamnă că merge, mai mult sau mai puțin, pentru o mână de prieteni. Nu există pagină de prețuri, buletin informativ sau plan de creștere. Dacă ți se pare util, poți cere să-l încerci când se deschide puțin mai mult."]},{"n":144,"texts":["AI-gile este o tablă kanban pentru un om și o mulțime de agenți AI. Rulează pe propriul tău calculator și este complet gratuită. Adaugi proiecte, iar fiecare proiect primește un lider și o echipă mică. Vorbești cu liderul, cam ca pe Discord, și îi descrii o idee; el o transformă în carduri și într-un plan, apoi așteaptă să apeși Go. Echipa parcurge cardurile în ordinea priorității, folosind o linie de comandă simplă, făcută pentru modelele de limbaj. Înainte să-ți revină ceva, un tester AI urmează pașii într-o copie a aplicației și atașează o captură de ecran. Munca terminată ajunge în grămada ta, cu fișierele schimbate și diferențele. O accepți sau lași un comentariu, iar echipa se trezește și mai încearcă. Doar tu poți muta un card la Gata.","O zi cu AI-gile, în mare. Seara lași câteva comentarii: butonul ăsta e într-un loc nepotrivit, lista aceea ar trebui sortată, am putea avea o temă întunecată. Te duci la culcare. Agenții citesc comentariile, fac schimbările, le testează și ți le dau înapoi. Dacă De făcut rămâne gol, veghea de noapte îl umple din backlog cu carduri care nu cer niciun răspuns de la tine. Dimineața e o singură grămadă scurtă: două întrebări și câteva lucruri de încercat, fiecare cu pași pe care îi poate urma un om somnoros și cu o captură de ecran în care merge. Dai clic prin ele, accepți ce e bun și trimiți înapoi restul. Un contor de tokeni arată cât s-a folosit, iar Modul fără tokeni e pentru săptămânile slabe. Apoi iei micul dejun, la care agenții încă nu pot ajuta.","Mai întâi, ce nu este AI-gile. Nu e un start-up, nu e de vânzare și nimeni nu-ți adună datele. E o tablă gratuită care rulează pe calculatorul tău, fără conturi, fără urmăritoare și fără cookie-uri. Ce este: un singur loc ordonat unde vezi toate proiectele de programare cu AI deodată, cu o echipă de agenți care fac cardurile și tu care iei deciziile. Unește cardurile înrudite, repară titlurile încurcate și urmărește cât de suplu rămâne codul. Vorbește vreo 120 de limbi, de la neerlandeză și flamandă până la limba piraților și klingoniană. Prietenii își pot scrie unii altora, în privat și criptat. A fost construit de Rich și de o mulțime de agenți răbdători, mai ales folosindu-se pe el însuși. E în pre-alfa închis, deci pe alocuri e aspru. Dacă ți se pare distractiv, cere frumos și poate intri mai devreme."]}],"quips":{"1":"Un cuvânt. Îndrăzneț. Poate prea îndrăzneț.","3":"Trei cuvinte. Deja mai cinstit decât majoritatea paginilor de produs.","8":"Opt cuvinte. Tot mai scurt decât un stand-up.","21":"Apropo, lungimile sunt puncte de poveste. Bineînțeles că sunt.","55":"Cincizeci și cinci de cuvinte. Două carduri s-au terminat cât ai citit.","144":"Asta e cea lungă. Nu există 233. Agenții s-au culcat."}},"timeline":{"first-idea.name":"Prima idee","first-idea.line":"Prima discuție, înainte să existe vreun rând de cod.","first-board.name":"Prima tablă","first-board.line":"O tablă care își urmărește propria construcție: carduri, coloane, tragere și plasare, proiecte.","team-roles.name":"Echipă și roluri","team-roles.line":"Profiluri de agenți, șabloane de echipă, spații și cine ce face.","install.name":"Instalare și versiuni","install.line":"Un zip pe care îl poate instala un prieten, actualizări automate, canale și revenire la versiunea veche.","usage-saver.name":"Economie de consum","usage-saver.line":"Măsori cât costă rulările, ții codul suplu, îți economisești limita.","friends.name":"Prieteni și partajare","friends.line":"Mesaje private, un releu criptat, invitații, roluri și proiecte partajate.","languages.name":"Limbi","languages.line":"Fiecare text din ecrane într-un fișier de limbă, cu neerlandeza și flamanda prima.","ai-tester.name":"Tester AI","ai-tester.line":"Un tester verifică fiecare predare mai întâi și arată ce a văzut.","website.name":"Site-ul","website.line":"aigile.lol, pagina de prezentare și această cronologie.","streaming.name":"Chat și streaming","streaming.line":"Discord, Twitch, OBS, modul de streamer, GIF-uri și emoji.","no-ai.name":"Ediția fără AI","no-ai.line":"O tablă pentru cei care programează fără AI, și table publice.","night-watch.name":"Veghea de noapte","night-watch.line":"Un paznic și un Scrum Master țin echipele la treabă cât dormi.","p-more.name":"Tot restul","p-more.line":"Idei mai mici care își așteaptă rândul.","p-android.name":"Telefon și Android","p-android.line":"Ajungi la tablă de pe telefon, apoi printr-o aplicație Android nativă.","p-release.name":"Alfa și mai departe","p-release.line":"Alfa închis, site-ul live, apoi beta.","p-languages.name":"Mai multe limbi","p-languages.line":"130 de limbi și un mod de imersiune pentru cei care învață.","p-engines.name":"Mai multe motoare AI","p-engines.line":"Alege Claude, Codex, Gemini, Copilot sau Cursor pentru fiecare agent.","p-pro.name":"Practică profesionistă","p-pro.line":"Etichete de risc, porți de îmbinare, carduri de incident și balustrade de siguranță.","p-self.name":"Grijă de tine","p-self.line":"Mod obosit, mementouri de îngrijire de sine și 4:20.","p-servers.name":"Servere și scară","p-servers.line":"Setări globale de server, roluri și planificare pentru creștere.","p-livestream.name":"Extra pentru streaming","p-livestream.line":"Chat Twitch, emoji proprii și o vedere publică live."},"words":{"button":"📖 Termeni de specialitate","h":"📖 Cuvinte explicate","intro":"Instruire gratuită pe înțelesul tuturor: fiecare cuvânt pe care îl întâlnești, de la prima idee până la un serviciu pe care se bazează oamenii, trecând pe parcurs prin Agile, construirea produsului, protejarea lui și lucrul cu AI.","search":"Caută un cuvânt…","none":"Niciun cuvânt nu se potrivește.","close":"Închide","count":{"one":"{count} cuvânt","other":"Cuvinte: {count}"},"groups":[{"id":"idea","name":"💡 Idei și descoperire"},{"id":"plan","name":"🗺️ Planificarea muncii"},{"id":"agile","name":"🔁 Metode de lucru Agile"},{"id":"build","name":"🛠️ Construirea"},{"id":"test","name":"🧪 Testare și calitate"},{"id":"change","name":"🔀 Modificări în siguranță"},{"id":"run","name":"🛎️ Rularea unui serviciu"},{"id":"sec","name":"🔒 Securitate și confidențialitate"},{"id":"ai","name":"🤖 Lucrul cu AI"},{"id":"money","name":"💰 Bani și licențe"}],"list":[{"id":"discovery","g":"idea","word":"Descoperire","text":"Etapa de început în care afli ce problemă merită rezolvată și pentru cine, înainte de a construi ceva.","also":["faza de descoperire","discovery"]},{"id":"problemstmt","g":"idea","word":"Enunțul problemei","text":"Una-două propoziții care spun cine are o problemă, în ce constă ea și de ce contează, ca toată lumea să urmărească același scop.","also":["enunțuri ale problemei","problem statement"]},{"id":"user","g":"idea","word":"Utilizator","text":"O persoană care folosește ceea ce construiești. Nevoile ei sunt rostul muncii.","also":["utilizatori","utilizatorul","user"],"noTip":1},{"id":"stakeholder","g":"idea","word":"Parte interesată","text":"Oricine e interesat de rezultatul muncii sau e afectat de el, cum sunt cei care plătesc, folosesc sau susțin produsul.","also":["părți interesate","stakeholder","stakeholderi"]},{"id":"persona","g":"idea","word":"Persona","text":"O persoană inventată, dar realistă, care reprezintă un fel de utilizator, ca echipa să se poată întreba „i-ar fi ușor lui Sam?”","also":["persone","personas"]},{"id":"userresearch","g":"idea","word":"Cercetare cu utilizatorii","text":"A vorbi cu oameni adevărați și a-i observa ca să afli ce le trebuie, în loc să ghicești.","also":["interviuri cu utilizatorii","user research"]},{"id":"journey","g":"idea","word":"Parcursul utilizatorului","text":"Pașii pe care îi face o persoană ca să ducă ceva la capăt, de când află prima oară de el până termină, inclusiv în afara produsului tău. Când îi desenezi, vezi unde se împotmolește.","also":["parcursuri","călătoria utilizatorului","user journey","customer journey"]},{"id":"painpoint","g":"idea","word":"Punct dureros","text":"Ceva care îi enervează sau îi încetinește pe oameni astăzi. Produsele bune elimină punctele dureroase.","also":["puncte dureroase","pain point"]},{"id":"assumption","g":"idea","word":"Presupunere","text":"Ceva ce crezi, dar n-ai verificat încă. Dacă notezi presupunerile, vezi ce merită testat întâi.","also":["presupuneri","assumption","ipoteză de lucru"],"noTip":1},{"id":"hypothesis","g":"idea","word":"Ipoteză","text":"O presupunere bine gândită pe care vrei s-o verifici, cu ce te aștepți să se întâmple, de exemplu „oamenii se vor înscrie dacă prima lună e gratis”.","also":["ipoteze","hypothesis"]},{"id":"experiment","g":"idea","word":"Experiment","text":"Un test mic și planificat prin care afli dacă o idee merge, înainte să mizezi mult pe ea.","also":["experimente","experimentul","experiment"],"noTip":1},{"id":"poc","g":"idea","word":"Dovadă de concept (PoC)","text":"O încercare rapidă și sumară ca să vezi dacă o idee poate funcționa măcar. De obicei se aruncă după ce ai răspunsul.","also":["PoC","proof of concept","demonstrarea conceptului"]},{"id":"prototype","g":"idea","word":"Prototip","text":"Un model timpuriu al produsului, adesea imagini pe care se poate da clic, ca să încerci ideea pe oameni înainte s-o construiești cum trebuie.","also":["prototipuri","prototipul","prototype"]},{"id":"wireframe","g":"idea","word":"Wireframe","text":"O schiță simplă a unui ecran care arată unde stă fiecare lucru, fără culori și fără conținut real.","also":["wireframe-uri","wireframe-ul","schiță de ecran"]},{"id":"mockup","g":"idea","word":"Machetă","text":"O imagine detaliată a felului în care va arăta un ecran, cu culori și texte reale, dar încă nu funcționează nimic.","also":["machete","macheta","mockup","mock-up","mockup-uri"]},{"id":"bizcase","g":"idea","word":"Studiu de oportunitate","text":"Motivele pentru care faci un proiect: cât costă, ce aduce sau ce economisește și ce riscuri are.","also":["studii de oportunitate","business case","analiză de oportunitate"]},{"id":"feasibility","g":"idea","word":"Fezabilitate","text":"Dacă un lucru poate fi cu adevărat construit și întreținut cu timpul, banii și cunoștințele pe care le ai.","also":["fezabil","fezabilitatea","feasibility"]},{"id":"outcome","g":"idea","word":"Rezultat","text":"Schimbarea pe care o vrei pentru oameni, de exemplu mai puține programări ratate. Contează mai mult decât cât construiești.","also":["rezultate","rezultatul","outcome","efect"],"noTip":1},{"id":"output","g":"idea","word":"Output (ce produce echipa)","text":"Ceva ce face echipa, de exemplu un ecran nou sau un raport. Faptul că l-ai făcut nu înseamnă automat că ajută pe cineva.","also":["output-uri","output","ieșire","produs al muncii"],"noTip":1},{"id":"successmetric","g":"idea","word":"Indicator de succes","text":"Un număr care îți spune dacă munca și-a atins scopul, de exemplu faptul că mai mulți oameni își finalizează comanda.","also":["indicatori de succes","success metric"]},{"id":"kpi","g":"idea","word":"Indicator cheie de performanță (KPI)","text":"Un număr important pe care îl urmărești ca să vezi dacă lucrurile merg bine, de exemplu înscrierile pe săptămână.","also":["KPI","KPI-uri","indicator cheie de performanță","key performance indicator"]},{"id":"okr","g":"idea","word":"Obiective și rezultate-cheie (OKR)","text":"O metodă de a-ți stabili ținte: obiectivul spune ce vrei, iar câteva rezultate-cheie sunt numerele care arată că ai ajuns acolo.","also":["OKR","OKR-uri"]},{"id":"product","g":"plan","word":"Produs","text":"Lucrul care e construit și întreținut pentru utilizatorii lui, de exemplu o aplicație, un site sau o unealtă.","also":["produse","produsul","product"],"noTip":1},{"id":"vision","g":"plan","word":"Viziunea produsului","text":"O declarație scurtă despre pe cine ajută produsul și încotro se îndreaptă pe termen lung.","also":["viziune","declarație de viziune","vision statement"]},{"id":"po","g":"plan","word":"Proprietarul produsului (PO)","text":"Persoana care hotărăște ce se construiește și în ce ordine, ca echipa să lucreze mereu la ce contează cel mai mult. În AI-gile, acela ești tu.","also":["PO","product owner","proprietar de produs"]},{"id":"pm","g":"plan","word":"Manager de produs (PM)","text":"Persoana care se ocupă de direcția unui produs: ce probleme rezolvă, pentru cine și de ce. PM poate însemna și manager de proiect, așa că verifică despre care e vorba.","also":["PM","product manager","manageri de produs"]},{"id":"projmgr","g":"plan","word":"Manager de proiect","text":"Persoana care ține un proiect la timp și în buget, urmărind cine face ce și până când.","also":["manageri de proiect","project manager"]},{"id":"roadmap","g":"plan","word":"Foaie de parcurs","text":"Un plan aproximativ al celor ce urmează în lunile următoare, în ordine. Arată direcția, nu date exacte, și se schimbă pe măsură ce înveți.","also":["foi de parcurs","roadmap"]},{"id":"milestone","g":"plan","word":"Etapă cheie","text":"Un punct dintr-un proiect care merită marcat, de exemplu „prima versiune e live” sau „100 de utilizatori”.","also":["etape cheie","jalon","jaloane","milestone"]},{"id":"mvp","g":"plan","word":"Produs minim viabil (MVP)","text":"Cea mai mică variantă a unui produs care e totuși utilă pentru oameni adevărați, ca să înveți de la ei din timp.","also":["MVP","MVP-uri","produs minim viabil","minimum viable product"]},{"id":"requirement","g":"plan","word":"Cerință","text":"Ceva ce produsul gata trebuie să facă sau să fie.","also":["cerințe","cerința","requirement"],"noTip":1},{"id":"scope","g":"plan","word":"Domeniul de lucru","text":"Ce intră în lucrare și, la fel de important, ce nu intră.","also":["scope","în domeniu","în afara domeniului","sfera lucrării"]},{"id":"scopecreep","g":"plan","word":"Extinderea necontrolată","text":"Când se tot adaugă câte puțin la lucrare, fără ca cineva să fi căzut de acord asupra timpului sau costului în plus, așa că nu se mai termină niciodată de-a binelea.","also":["scope creep","feature creep","extindere a domeniului"]},{"id":"feature","g":"plan","word":"Funcționalitate","text":"Un lucru pe care produsul îl poate face pentru oameni, de exemplu „resetarea parolei”.","also":["funcționalități","funcționalitatea","feature","feature-uri"],"noTip":1},{"id":"epic","g":"plan","word":"Epic","text":"O bucată mare de muncă, prea mare ca să fie făcută dintr-odată, așa că se împarte în carduri mai mici.","also":["epice","epic-uri","epicul"]},{"id":"story","g":"plan","word":"Poveste de utilizator","text":"O bucată mică de muncă scrisă din partea utilizatorului: „Ca cumpărător, vreau să-mi salvez coșul, ca să pot termina mai târziu.” Pornește o discuție despre ce să construiești.","also":["povești de utilizator","user story"]},{"id":"ac","g":"plan","word":"Criterii de acceptare (AC)","text":"Verificările pe care un card trebuie să le treacă ca să se considere gata, stabilite înainte să înceapă munca, de exemplu „coșul e tot acolo după ce mă deconectez și mă conectez la loc”.","also":["AC","criterii de acceptare","acceptance criteria"]},{"id":"task","g":"plan","word":"Sarcină","text":"O singură treabă de făcut, adesea un pas mic dintr-o poveste mai mare.","also":["sarcini","sarcina","task","task-uri"],"noTip":1},{"id":"ticket","g":"plan","word":"Tichet","text":"Alt cuvânt pentru card: o bucată de muncă sau o cerere, urmărită de la început până la sfârșit.","also":["tichete","tichetul","ticket","ticket-uri"]},{"id":"priority","g":"plan","word":"Prioritate","text":"Cât de important sau de urgent e ceva în comparație cu tot restul, ca munca cea mai importantă să meargă prima.","also":["priorități","prioritatea","priority"],"noTip":1},{"id":"prioritise","g":"plan","word":"Prioritizare","text":"Așezarea muncii în ordinea importanței. O metodă obișnuită e MoSCoW: Must have (obligatoriu), Should have (ar trebui), Could have (ar fi bine), Won’t have (nu de data asta).","also":["a prioritiza","prioritizăm","MoSCoW"]},{"id":"estimate","g":"plan","word":"Estimare","text":"O apreciere cât mai bună a cât de mare sau cât de lungă e o bucată de muncă. E o presupunere, nu o promisiune.","also":["estimări","estimarea","a estima","estimate"],"noTip":1},{"id":"storypoints","g":"plan","word":"Story points","text":"O metodă de a ghici mărimea muncii comparând cardurile între ele („cam de două ori cât celălalt”) în loc să o măsori în ore. Nu servesc la compararea echipelor.","also":["story point","puncte de poveste","story pointuri"]},{"id":"tshirt","g":"plan","word":"Mărimi de tricou","text":"Ghicirea mărimii muncii ca S, M, L sau XL. E rapid și destul de bun pentru planificarea de la început.","also":["mărimi de tricou","estimare pe mărimi de tricou","T-shirt sizing","t-shirt sizes"]},{"id":"poker","g":"plan","word":"Planning poker","text":"Un joc pentru estimare: toți arată în același timp o carte cu o mărime, apoi cel cu cea mai mare și cel cu cea mai mică explică de ce.","also":["Scrum poker","poker de planificare"]},{"id":"dependency","g":"plan","word":"Dependență","text":"Când o bucată de muncă nu poate începe sau nu se poate termina până nu se face alta.","also":["dependențe","dependency"]},{"id":"blocker","g":"plan","word":"Blocaj","text":"Orice oprește munca din loc chiar acum, de exemplu un răspuns care lipsește sau o unealtă stricată.","also":["blocaje","blocajul","blocker","blocker-uri"]},{"id":"deadline","g":"plan","word":"Termen limită","text":"Data până la care ceva trebuie terminat.","also":["termene limită","termenul limită","deadline"],"noTip":1},{"id":"deliverable","g":"plan","word":"Livrabil","text":"Ceva concret pe care îl produce munca și îl predă, de exemplu o pagină care merge sau un raport.","also":["livrabile","livrabilul","deliverable"]},{"id":"forecast","g":"plan","word":"Previziune","text":"O prognoză a ceea ce se va întâmpla probabil, de exemplu când va fi gata munca, pe baza a ce știi până acum.","also":["previziuni","prognoză","forecast"],"noTip":1},{"id":"metric","g":"plan","word":"Metrică","text":"Orice măsori și urmărești în timp, de exemplu vizitele pe pagină sau cât durează o remediere.","also":["metrici","metrica","metric"]},{"id":"feedback","g":"plan","word":"Feedback","text":"Ce îți spun oamenii despre munca ta, de bine și de rău. Să-l primești devreme și des e inima metodei Agile.","noTip":1},{"id":"backlog","g":"agile","word":"Backlog","text":"Lista de așteptare cu idei și muncă încă neplanificate, cu cele mai importante sus. Nimic de acolo nu se lucrează până nu trece în De făcut."},{"id":"sprint","g":"agile","word":"Sprint","text":"O perioadă scurtă și fixă de muncă (adesea una sau două săptămâni, niciodată mai mult de o lună), cu un scop și un set convenit de carduri de terminat.","also":["sprinturi","sprinturile","sprintul","sprintului","sprinturilor"]},{"id":"standup","g":"agile","word":"Stand-up","text":"Un check-in rapid în fiecare zi: ce a făcut fiecare membru al echipei, ce face în continuare și ce îl oprește. În Scrum se numește scrum zilnic.","also":["standup","stand-up-uri","stand-up-ul","stand-upuri","scrum zilnic","stand-up zilnic"]},{"id":"kanban","g":"agile","word":"Kanban","text":"O metodă de lucru în care cardurile se mută prin coloanele unui board (de exemplu De făcut, În lucru, Gata), iar echipa limitează cât e în lucru deodată, ca munca să curgă."},{"id":"wip","g":"agile","word":"Limită WIP","text":"WIP vine de la work in progress, adică muncă în desfășurare. Limita WIP e numărul maxim de carduri pe care ar trebui să-l aibă o coloană deodată, ca echipa să termine lucrurile înainte să înceapă altele.","also":["WIP"]},{"id":"dod","g":"agile","word":"Definiția pentru Terminat","text":"Lista scurtă a echipei despre ce înseamnă „gata”, de exemplu testat și explicat, înainte ca un card să ajungă la tine. Geamăna ei, Definiția pentru Gata de start, spune când un card e destul de clar ca să fie început.","also":["Definition of Ready","DoD","DoR","Definiția pentru Gata de start"]},{"id":"retro","g":"agile","word":"Retro","text":"O privire regulată înapoi la cum lucrează echipa, ca să stabiliți unul-două lucruri de făcut mai bine data viitoare. Prescurtare de la retrospectivă. În AI-gile, o retro propune o schimbare în felul de lucru al echipei, iar tu spui Go sau Încă nu.","also":["retrospectivă","retrospective"]},{"id":"swarm","g":"agile","word":"Roi","text":"Toată lumea la treabă: mulți lasă deoparte altă muncă ca să repare împreună un lucru urgent până se rezolvă. În AI-gile, fiecare echipă ajută la un singur proiect, iar celelalte proiecte așteaptă între timp.","also":["roiul","swarm","swarming"]},{"id":"scrummaster","g":"agile","word":"Scrum Master","text":"În Scrum, persoana care ajută echipa să lucreze bine: înlătură ce o blochează, ține întâlnirile pe făgaș și îndrumă spre obiceiuri bune, fără să dea ordine. În AI-gile, Lead Scrum Master observă cardurile blocate, îndeamnă echipele și îți amintește ce așteaptă, în toate proiectele.","also":["Lead Scrum Master"]},{"id":"agile","g":"agile","word":"Agile","text":"O metodă de a lucra în pași mici: construiești puțin, arăți des rezultate reale, înveți din ce spun oamenii și schimbi planul pe parcurs, în loc să planifici totul de la început.","also":["dezvoltare Agile","metode de lucru Agile","agil","Agile development","agile ways of working"]},{"id":"manifesto","g":"agile","word":"Manifestul Agile","text":"O declarație scurtă scrisă în 2001 de oameni care fac software. Pune oamenii, rezultatele care merg, colaborarea strânsă cu clienții și adaptarea la schimbare înaintea planurilor grele și a hârtiilor.","also":["Manifestul pentru dezvoltarea agilă de software","Agile Manifesto"]},{"id":"waterfall","g":"agile","word":"Cascadă","text":"Metoda mai veche de lucru: planifici totul, apoi construiești totul, apoi testezi totul, o etapă după alta. Schimbările târzii sunt grele și costisitoare.","also":["model în cascadă","waterfall"]},{"id":"iteration","g":"agile","word":"Iterație","text":"O rundă în care construiești ceva, îl verifici și îl îmbunătățești. Munca Agile e un lanț de asemenea runde, iar sprintul este un fel de iterație.","also":["iterații","iterația","iteration"]},{"id":"increment","g":"agile","word":"Increment","text":"O bucată nouă care funcționează, adăugată produsului într-un sprint sau într-o rundă de lucru, și care se potrivește cu ce era deja acolo.","also":["incremente","incrementul","increment"]},{"id":"scrum","g":"agile","word":"Scrum","text":"O metodă Agile populară: o echipă mică lucrează în sprinturi scurte spre un scop, cu roluri fixe și câteva întâlniri regulate pentru a planifica, a verifica și a îmbunătăți."},{"id":"scrumteam","g":"agile","word":"Echipa Scrum","text":"Grupul mic care face munca în Scrum: un proprietar de produs, un Scrum Master și dezvoltatorii.","also":["echipe Scrum","echipa Scrum","Scrum team"]},{"id":"ceremonies","g":"agile","word":"Evenimentele Scrum","text":"Întâlnirile regulate din Scrum: planificarea sprintului, scrumul zilnic, analiza sprintului (sprint review) și retrospectiva. Mulți le spun ceremonii.","also":["ceremonii","ceremoniile Scrum","Scrum ceremonies","ceremonies"]},{"id":"sprintplan","g":"agile","word":"Planificarea sprintului","text":"Întâlnirea de la începutul unui sprint în care echipa hotărăște de ce contează sprintul, ce carduri ia și cum începe.","also":["întâlnire de planificare","sprint planning"]},{"id":"sprintgoal","g":"agile","word":"Scopul sprintului","text":"O propoziție care spune la ce servește un sprint. Sarcinile mici se pot schimba pe parcurs, atâta timp cât scopul se atinge.","also":["scopuri ale sprintului","obiectivul sprintului","sprint goal"]},{"id":"sprintbacklog","g":"agile","word":"Backlogul sprintului","text":"Cardurile alese pentru sprintul curent, cu planul echipei de a le face.","also":["sprint backlog","backlog de sprint"]},{"id":"productbacklog","g":"agile","word":"Backlogul produsului","text":"Lista completă și ordonată a tot ce s-ar putea construi pentru produs, cu cel mai important sus. Se schimbă mereu pe măsură ce înveți.","also":["product backlog","backlog de produs"]},{"id":"productgoal","g":"agile","word":"Scopul produsului","text":"Rezultatul mai mare spre care tinde produsul și care ajută echipa să aleagă ce urmează.","also":["scopuri ale produsului","obiectivul produsului","product goal"]},{"id":"refinement","g":"agile","word":"Rafinarea backlogului","text":"Parcurgerea regulată a backlogului pentru a face ordine în carduri, a le împărți, a le ordona și a le completa cu detalii, ca să fie gata de preluat. Se mai numește și backlog grooming.","also":["backlog refinement","backlog grooming","rafinare","refinement"]},{"id":"sprintreview","g":"agile","word":"Analiza sprintului (sprint review)","text":"O întâlnire la sfârșitul sprintului în care echipa arată ce a terminat și află ce cred oamenii, ca să hotărască ce urmează.","also":["sprint review","demonstrația sprintului","prezentarea sprintului","sprint demo"]},{"id":"demo","g":"agile","word":"Demo","text":"Prezentarea în direct a muncii terminate, în funcțiune, celor care au cerut-o.","also":["demonstrație","demo-uri","demonstrații"],"noTip":1},{"id":"timebox","g":"agile","word":"Timebox","text":"Un interval fix de timp alocat pentru ceva. Când se termină, te oprești, chiar dacă nu e totul gata.","also":["cadru de timp","timeboxed","timeboxes","limită de timp"]},{"id":"velocity","g":"agile","word":"Viteza echipei","text":"Câtă muncă termină de obicei o echipă într-un sprint; te ajută să planifici cât să preia data viitoare. Nu e un scor pentru cât de tare muncesc oamenii.","also":["viteză","velocity","team velocity"]},{"id":"capacity","g":"agile","word":"Capacitate","text":"Cât de multă muncă poate prelua echipa într-o perioadă, după vacanțe și alte treburi.","noTip":1},{"id":"burndown","g":"agile","word":"Grafic burndown","text":"Un grafic al muncii rămase într-un sprint, care coboară zi de zi. Dacă linia rămâne plată, ceva s-a blocat.","also":["burndown","burn-down","burndown chart"]},{"id":"burnup","g":"agile","word":"Grafic burnup","text":"Un grafic al muncii terminate care urcă în timp, alături de totalul planificat, ca să vezi când ajungi.","also":["burnup","burn-up","burnup chart"]},{"id":"kanbanboard","g":"agile","word":"Board Kanban","text":"Board-ul însuși: câte o coloană pentru fiecare etapă a muncii, cu carduri care se mută de la una la alta.","also":["board-uri Kanban","Kanban board"]},{"id":"pullsys","g":"agile","word":"Sistem „pull”","text":"O metodă de lucru în care o muncă nouă începe doar când cineva are loc să o preia, în loc să fie împinsă spre cineva care are deja prea multe pe cap.","also":["sistem pull","pull system","pull-based"]},{"id":"flow","g":"agile","word":"Flux","text":"Cât de lin se mișcă munca pe board. Un flux bun înseamnă că cardurile avansează, nu se adună grămadă.","also":["fluxul de lucru","flow","fluxul muncii"],"noTip":1},{"id":"leadtime","g":"agile","word":"Timp total de livrare","text":"Cât durează de când cere cineva ceva până când e gata.","also":["lead time","timpul de livrare"]},{"id":"cycletime","g":"agile","word":"Timp de ciclu","text":"Cât durează un card de când începe cu adevărat munca la el până când e terminat.","also":["cycle time","timpul de ciclu"]},{"id":"throughput","g":"agile","word":"Throughput (debit)","text":"Câte carduri se termină într-o săptămână sau în orice interval stabilit.","also":["debit","debitul","throughput","rată de livrare"]},{"id":"bottleneck","g":"agile","word":"Gât de sticlă","text":"Etapa unde munca se adună și încetinește tot ce urmează după ea, ca gâtul îngust al unei sticle.","also":["gâtuire","gâtuiri","bottleneck"]},{"id":"swimlane","g":"agile","word":"Culoar","text":"Un rând de-a lungul board-ului care grupează carduri de același fel, de exemplu munca urgentă sau cardurile unei echipe.","also":["culoare","swimlane","swim lane"]},{"id":"lean","g":"agile","word":"Lean","text":"O metodă de lucru care taie risipa (tot ce nu ajută clientul) și ține munca în mișcare."},{"id":"waste","g":"agile","word":"Risipă","text":"În Lean, tot ce cere efort, dar nu ajută clientul, de exemplu așteptarea, refacerea sau construirea unor lucruri pe care nu le folosește nimeni.","noTip":1},{"id":"kaizen","g":"agile","word":"Îmbunătățire continuă","text":"A deveni mereu puțin mai bun prin schimbări mici și regulate, apoi a verifica dacă au ajutat. Retrospectivele sunt un mod de a o face. Se mai numește kaizen.","also":["kaizen"]},{"id":"selforg","g":"agile","word":"Echipă auto-organizată","text":"O echipă care hotărăște singură cum face munca, în loc să i se spună pas cu pas.","also":["echipă care se auto-organizează","echipă autonomă","self-organising"]},{"id":"crossfunc","g":"agile","word":"Echipă multifuncțională","text":"O echipă care are toate aptitudinile de care are nevoie ca să termine singură munca, de exemplu design, construcție și testare.","also":["echipe multifuncționale","cross-functional"]},{"id":"spike","g":"agile","word":"Spike","text":"O cercetare scurtă, cu timp limitat, ca să răspunzi la o întrebare înainte să te angajezi la munca propriu-zisă.","also":["spike-uri","spike-ul","cercetare scurtă"]},{"id":"rework","g":"agile","word":"Refacere","text":"A face munca din nou pentru că nu a fost bună din prima.","also":["refaceri","rework","muncă refăcută"]},{"id":"safe","g":"agile","word":"Agile la scară (SAFe)","text":"Moduri de a folosi Agile în multe echipe dintr-o organizație mare. SAFe (Scaled Agile Framework) este un exemplu binecunoscut.","also":["Scaled Agile","Agile scalat"]},{"id":"repo","g":"build","word":"Repo","text":"Dosarul de cod al proiectului, cu tot istoricul de commit-uri. Poate sta pe calculatorul tău, pe GitHub sau în ambele locuri.","also":["repository","repo-ul","repo-uri"]},{"id":"branch","g":"build","word":"Branch","text":"O linie de lucru separată în cod, ca să poți face modificări fără să atingi versiunea principală.","also":["branch-uri","branch-ul","branch-urile"]},{"id":"commit","g":"build","word":"Commit","text":"Un instantaneu salvat al codului, cu o scurtă notă despre ce s-a schimbat. Poți reveni oricând la el.","also":["commit-uri","commit-ul","commit-urile"]},{"id":"push","g":"build","word":"Push","text":"Trimiterea instantaneelor tale salvate (commit-uri) de pe acest calculator în copia comună de pe internet, de exemplu GitHub, ca să existe o copie de siguranță și să le poată prelua și alții."},{"id":"merge","g":"build","word":"Merge","text":"Îmbinarea modificărilor dintr-un branch în altul, de obicei înapoi în versiunea principală."},{"id":"pr","g":"build","word":"Pull request","text":"O cerere ca modificările unui branch să fie verificate și îmbinate în versiunea principală. Unele site-uri îi spun merge request.","also":["PR","PR-uri","merge request"]},{"id":"refactor","g":"build","word":"Refactor","text":"Curățarea codului fără a-i schimba funcția: fișiere mai mici, nume mai clare, mai puține repetiții."},{"id":"bug","g":"build","word":"Bug","text":"Ceva care nu funcționează așa cum ar trebui.","also":["bug-uri","bug-ul","bug-urile","bug-urilor"]},{"id":"peerreview","g":"build","word":"Revizuire de către colegi","text":"O a doua pereche de ochi: altcineva decât autorul verifică munca înainte să ajungă la tine, ca să treacă mai puține greșeli. În AI-gile, un alt AI verifică fiecare card.","also":["peer review","code review","revizuire de cod"]},{"id":"code","g":"build","word":"Cod","text":"Instrucțiunile scrise care spun unui calculator ce să facă. Se mai numește și cod sursă.","also":["cod sursă","codul","source code"],"noTip":1},{"id":"proglang","g":"build","word":"Limbaj de programare","text":"Un limbaj în care se scrie cod, de exemplu JavaScript, Python sau Java. Fiecare se potrivește altor treburi.","also":["limbaje de programare"]},{"id":"developer","g":"build","word":"Dezvoltator (dev)","text":"Cineva care scrie și schimbă cod. Se mai spune programator sau inginer software.","also":["dezvoltatori","dezvoltatorul","programator","programatori","inginer software","developer"]},{"id":"software","g":"build","word":"Software","text":"Programele care rulează pe calculatoare și pe telefoane, spre deosebire de aparatele în sine (hardware).","noTip":1},{"id":"app","g":"build","word":"Aplicație","text":"Un program pe care oamenii îl folosesc ca să ducă ceva la capăt, pe telefon, pe calculator sau într-un browser.","also":["aplicații","aplicația","app","app-uri"],"noTip":1},{"id":"webapp","g":"build","word":"Aplicație web","text":"O aplicație care rulează într-un browser, așa că nu e nimic de instalat.","also":["aplicații web","web app","webapp"]},{"id":"frontend","g":"build","word":"Front end","text":"Partea unei aplicații pe care o vezi și pe care dai clic: ecranele, butoanele și cuvintele, adesea în browser.","also":["front-end","frontend","partea din față"]},{"id":"backend","g":"build","word":"Back end","text":"Partea din spatele scenei a unei aplicații, care păstrează datele și face munca atunci când dai clic pe ceva, de exemplu când îți verifică parola.","also":["back-end","backend","partea din spate"]},{"id":"fullstack","g":"build","word":"Full stack","text":"A lucra și la front end, și la back end.","also":["full-stack"]},{"id":"ui","g":"build","word":"Interfața utilizatorului (UI)","text":"Ce vede și folosește o persoană pe ecran: aspectul, butoanele, meniurile și textul.","also":["UI","interfață","user interface"]},{"id":"ux","g":"build","word":"Experiența utilizatorului (UX)","text":"Cum e să folosești ceva: ușor, clar și plăcut, sau derutant și lent.","also":["UX","experiența de utilizare","user experience"]},{"id":"accessibility","g":"build","word":"Accesibilitate (a11y)","text":"A face lucrurile utilizabile de către toată lumea, inclusiv de oamenii care nu văd bine, nu pot folosi un mouse sau folosesc un cititor de ecran.","also":["a11y","accesibil"]},{"id":"responsive","g":"build","word":"Design adaptabil","text":"A face paginile să se potrivească și să funcționeze bine pe orice dimensiune de ecran, de la telefon la un monitor mare.","also":["design responsive"]},{"id":"designsys","g":"build","word":"Sistem de design","text":"Un set comun de culori, fonturi, butoane și reguli, ca fiecare ecran să arate și să se poarte la fel.","also":["sisteme de design","design system"]},{"id":"architecture","g":"build","word":"Arhitectură","text":"Forma de ansamblu a unui sistem: care sunt părțile principale și cum comunică între ele."},{"id":"database","g":"build","word":"Bază de date (DB)","text":"Un loc organizat în care se țin informații, ca o foaie de calcul foarte puternică pe care aplicația o poate citi și schimba.","also":["baze de date","baza de date","database","DB"]},{"id":"schema","g":"build","word":"Schema bazei de date","text":"Felul în care e aranjată o bază de date: ce tabele de informații are și ce intră în fiecare.","also":["schemă","schema","database schema"]},{"id":"sql","g":"build","word":"SQL","text":"Prescurtarea de la structured query language (limbaj de interogare structurat): limbajul prin care ceri informații de la multe baze de date sau le modifici datele.","also":["Structured Query Language","limbaj de interogare structurat"]},{"id":"data","g":"build","word":"Date","text":"Informații păstrate de un calculator, de exemplu nume, comenzi sau setări.","also":["datele","set de date","seturi de date","dataset","datasets"],"noTip":1},{"id":"server","g":"build","word":"Server","text":"Un calculator care e mereu pornit și răspunde la cererile altor calculatoare, de exemplu trimite o pagină web când o vizitezi.","also":["servere","serverul","serverele"]},{"id":"client","g":"build","word":"Client","text":"Partea care cere ceva, de obicei browserul sau aplicația ta, și vorbește cu un server. În afaceri, cuvântul înseamnă pur și simplu un client care cumpără.","also":["clienți","clientul","client"],"noTip":1},{"id":"api","g":"build","word":"API","text":"Prescurtarea de la application programming interface (interfață de programare a aplicațiilor): un meniu fix de cereri pe care un program le poate face altuia, de exemplu când ceri unui serviciu meteo prognoza de azi.","also":["API-uri","API-ul","application programming interface","interfață de programare"]},{"id":"endpoint","g":"build","word":"Endpoint","text":"Un articol din meniul unui API: o adresă web pe care un program o poate apela ca să primească sau să trimită ceva.","also":["endpoint-uri","endpoint-ul","punct de acces"]},{"id":"integration","g":"build","word":"Integrare","text":"Legarea a două sisteme ca să lucreze împreună, de exemplu magazinul tău care trimite comenzile către programul de contabilitate.","also":["integrări","integrarea","integration"]},{"id":"webhook","g":"build","word":"Webhook","text":"Un mesaj pe care un sistem îl trimite singur altuia în clipa în care se întâmplă ceva, de exemplu „plată primită”.","also":["webhook-uri","webhook-ul"]},{"id":"library","g":"build","word":"Bibliotecă","text":"Cod gata făcut, scris de altcineva, pe care îl poți reutiliza în loc să-l scrii tu.","also":["biblioteci","biblioteca","library"],"noTip":1},{"id":"framework","g":"build","word":"Framework","text":"O structură gata făcută pentru a construi o aplicație, care hotărăște mare parte din felul în care e aranjat codul, ca scheletul unei case pe care îl completezi.","also":["framework-uri","framework-ul","cadru de lucru"]},{"id":"sdk","g":"build","word":"Kit de dezvoltare software (SDK)","text":"O cutie cu unelte, cod și exemple pentru a construi software pentru o platformă sau un serviciu.","also":["SDK","SDK-uri","software development kit"]},{"id":"softdep","g":"build","word":"Dependență software","text":"O bibliotecă sau o unealtă de care codul tău are nevoie ca să funcționeze. E important să le ții la zi, pentru siguranță.","also":["dependențe software","software dependency"]},{"id":"package","g":"build","word":"Pachet","text":"Un set de cod gata făcut pe care îl poți instala și folosi într-un proiect.","also":["pachete","pachetul","package"],"noTip":1},{"id":"pkgmgr","g":"build","word":"Manager de pachete","text":"O unealtă care aduce și actualizează pachetele de care depinde codul tău. npm este una des întâlnită.","also":["manageri de pachete","package manager","npm"]},{"id":"git","g":"build","word":"Git","text":"Cea mai folosită unealtă pentru păstrarea istoricului modificărilor de cod, sub formă de commit-uri și branch-uri."},{"id":"github","g":"build","word":"GitHub","text":"Un site care ține online depozitele Git, ca echipele să poată partaja cod, revizui modificări și urmări munca."},{"id":"vcs","g":"build","word":"Control al versiunilor","text":"Păstrarea istoricului complet al fiecărei modificări a fișierelor, ca să vezi cine a schimbat ce și să te poți întoarce la nevoie. Git face asta.","also":["controlul versiunilor","sistem de control al versiunilor","version control","source control"]},{"id":"clone","g":"build","word":"Clonare","text":"A-ți face propria copie completă a unui repo, cu tot cu istoric, pe calculatorul tău.","also":["a clona","clonat","clone","clonezi"]},{"id":"pull","g":"build","word":"Pull","text":"A aduce ultimele commit-uri din copia comună (de exemplu GitHub) pe calculatorul tău. Opusul lui push.","also":["git pull","pull-uri","a trage"],"noTip":1},{"id":"mainbranch","g":"build","word":"Ramura principală","text":"Versiunea oficială a codului de la care pornește toată lumea, numită adesea main sau master.","also":["ramura main","main branch","master branch","main","master"]},{"id":"conflict","g":"build","word":"Conflict de merge","text":"Când două modificări ating aceleași rânduri în feluri diferite, așa că calculatorul nu le poate îmbina și trebuie să aleagă un om.","also":["conflicte de merge","conflict la îmbinare","merge conflict"]},{"id":"diff","g":"build","word":"Diff","text":"O afișare care arată exact ce s-a schimbat între două versiuni: rândurile adăugate și cele scoase.","also":["diff-uri","diff-ul","diferențe"]},{"id":"fork","g":"build","word":"Fork","text":"Propria ta copie a repo-ului altcuiva, pe care o poți schimba fără să afectezi originalul.","also":["fork-uri","fork-ul","a face fork"]},{"id":"script","g":"build","word":"Script","text":"Un program scurt care face singur o treabă, de exemplu pune fișierele în ordine sau pornește aplicația.","also":["scripturi","scriptul","script"],"noTip":1},{"id":"build","g":"build","word":"Build","text":"A transforma codul în ceva gata de rulat, sau rezultatul gata de rulat în sine.","also":["build-uri","build-ul","compilare"],"noTip":1},{"id":"compile","g":"build","word":"Compilare","text":"A traduce codul scris de oameni într-o formă pe care calculatorul o poate rula direct.","also":["a compila","compilat","compilator","compile","compiler"]},{"id":"cli","g":"build","word":"Linie de comandă (CLI)","text":"O fereastră de text în care scrii instrucțiuni pentru calculator în loc să dai clic. Se mai numește terminal.","also":["linia de comandă","terminal","CLI","command line"]},{"id":"config","g":"build","word":"Configurare (config)","text":"Setările care controlează cum se comportă un software, ținute separat de cod ca să fie ușor de schimbat.","also":["config","configurație","configuration"],"noTip":1},{"id":"envvar","g":"build","word":"Variabilă de mediu","text":"O setare dată unui program când pornește, folosită adesea pentru adrese sau parole, ca să nu fie scrise în cod.","also":["variabile de mediu","environment variable","env var"]},{"id":"debugging","g":"build","word":"Depanare","text":"A căuta de ce nu merge ceva și a-l repara.","also":["a depana","debug","debugging","debuguire"]},{"id":"pairing","g":"build","word":"Programare în pereche","text":"Două persoane (sau o persoană și un AI) care lucrează împreună la același cod: una scrie, cealaltă verifică.","also":["pair programming","pairing"]},{"id":"docs","g":"build","word":"Documentație (docs)","text":"Explicații scrise despre cum funcționează ceva sau cum se folosește.","also":["documentația","documentație","docs"],"noTip":1},{"id":"readme","g":"build","word":"README","text":"Primul fișier de citit dintr-un repo: ce este proiectul și cum îl pornești.","also":["README-uri","readme","fișierul README"]},{"id":"legacy","g":"build","word":"Sistem moștenit","text":"Un sistem mai vechi, încă folosit, greu de schimbat, adesea pentru că îl mai înțeleg puțini oameni.","also":["sisteme moștenite","legacy system","legacy code","legacy"]},{"id":"techdebt","g":"build","word":"Datorie tehnică","text":"Scurtături care economisesc timp acum, dar fac schimbările de mai târziu mai lente, ca un împrumut pe care se adună dobândă. Refactorizarea o achită.","also":["datorii tehnice","tech debt","technical debt"]},{"id":"test","g":"test","word":"Test","text":"O verificare că ceva funcționează cum trebuie. Unele teste le rulează calculatorul singur de fiecare dată când se schimbă codul; la altele încerci tu un card terminat înainte să-l accepți.","also":["teste","testul","testului","testare","testat","testezi","testarea"],"noTip":1},{"id":"qa","g":"test","word":"QA","text":"Prescurtarea de la quality assurance, asigurarea calității: tot ce se face pentru a te asigura că munca e corectă înainte să ajungă live. În AI-gile înseamnă verificările automate: când QA e roșu, ceva a picat și nu poate ajunge live până nu se repară.","also":["asigurarea calității","verificări de calitate"]},{"id":"testpile","g":"test","word":"Grămada de teste","text":"Cardurile terminate care așteaptă să le încerci, unul după altul. Acceptă unul sau trimite-l înapoi cu o notă, și vine următorul.","also":["grămezi de teste","test pile"]},{"id":"autotest","g":"test","word":"Test automat","text":"O verificare pe care calculatorul o rulează singur de fiecare dată când se schimbă codul, ca să prindă greșelile din timp.","also":["teste automate","automated test","automatic tests"]},{"id":"manualtest","g":"test","word":"Test manual","text":"O persoană care încearcă de mână rezultatul muncii, ca să vadă dacă se comportă cum trebuie.","also":["teste manuale","testare manuală","manual testing"]},{"id":"unittest","g":"test","word":"Test unitar","text":"O verificare automată mică a unei singure bucăți mici de cod, luate separat.","also":["teste unitare","unit test"]},{"id":"integtest","g":"test","word":"Test de integrare","text":"O verificare că mai multe părți lucrează bine împreună, nu doar pe rând.","also":["teste de integrare","integration test"]},{"id":"endtoend","g":"test","word":"Test cap-coadă (E2E)","text":"Un test care se comportă ca un utilizator real de la început până la sfârșit, de exemplu își creează un cont, cumpără și plătește.","also":["E2E","teste cap-coadă","teste end-to-end"]},{"id":"uat","g":"test","word":"Testare de acceptare de către utilizatori (UAT)","text":"Cei care au cerut munca o încearcă singuri și spun dacă face ce le trebuie. Grămada de teste din AI-gile este varianta lui.","also":["UAT","testare de acceptare","acceptance testing"]},{"id":"regression","g":"test","word":"Regresie","text":"Ceva ce mergea înainte, dar s-a stricat după o schimbare. Testele de regresie verifică dacă lucrurile vechi merg în continuare.","also":["regresii","regression","teste de regresie","test de regresie"]},{"id":"smoke","g":"test","word":"Test de fum","text":"O verificare foarte rapidă că lucrurile principale funcționează măcar, de exemplu imediat după ce o schimbare ajunge live. Dacă pică, oprește-te și uită-te.","also":["teste de fum","smoke test"]},{"id":"exploratory","g":"test","word":"Testare exploratorie","text":"A încerca produsul liber și a-l pune la încercare în tot felul de moduri, ca să găsești probleme pe care verificările planificate le-ar rata.","also":["test exploratoriu","exploratory testing"]},{"id":"testcase","g":"test","word":"Caz de test","text":"Un scenariu scris de încercat: pașii și ce ar trebui să se întâmple.","also":["cazuri de test","test case"]},{"id":"coverage","g":"test","word":"Acoperirea testelor","text":"Cât din cod este verificat de teste automate. Mai mult e de obicei mai sigur, dar o acoperire mare nu dovedește singură că merge bine.","also":["acoperire","acoperirea codului","code coverage"]},{"id":"testdata","g":"test","word":"Date de test","text":"Informații inventate, folosite la testare, ca să nu fie expuse datele private ale vreunei persoane reale.","also":["test data","date fictive"]},{"id":"edgecase","g":"test","word":"Caz limită","text":"O situație neobișnuită, la limită, de exemplu un formular gol sau un nume cu apostrof, în care lucrurile se strică adesea.","also":["cazuri limită","edge case"]},{"id":"happypath","g":"test","word":"Drumul fericit","text":"Drumul obișnuit în care totul merge bine. O testare bună încearcă și drumurile nefericite."},{"id":"perftest","g":"test","word":"Testare de performanță","text":"A verifica cât de rapid e ceva și cât de bine se descurcă sub presiune.","also":["test de performanță","teste de performanță","performance testing"]},{"id":"loadtest","g":"test","word":"Testare de încărcare","text":"A verifica cum se descurcă un sistem când îl folosesc mulți oameni deodată.","also":["test de încărcare","teste de încărcare","load testing"]},{"id":"sectest","g":"test","word":"Testare de securitate","text":"A căuta slăbiciuni prin care cineva ar putea folosi greșit un sistem sau ar putea vedea ce nu are voie să vadă.","also":["test de securitate","teste de securitate","security testing"]},{"id":"accesstest","g":"test","word":"Testare de accesibilitate","text":"A verifica dacă oamenii cu abilități diferite pot folosi produsul, inclusiv cu un cititor de ecran sau doar cu tastatura.","also":["test de accesibilitate","accessibility testing"]},{"id":"linting","g":"test","word":"Linting","text":"O verificare automată care găsește greșeli probabile și stil neîngrijit în cod, ca un corector ortografic pentru programe.","also":["linter","lint","linting-ul"]},{"id":"static","g":"test","word":"Analiză statică","text":"Verificarea automată a codului pentru probleme, prin citirea lui, fără a-l rula.","also":["analiza statică a codului","static analysis"]},{"id":"flaky","g":"test","word":"Test instabil","text":"Un test care uneori trece și alteori pică fără motiv clar, așa că nu te poți baza pe el pe deplin.","also":["teste instabile","flaky test","flaky"]},{"id":"repro","g":"test","word":"Reproducere (repro)","text":"A face un bug să apară din nou intenționat, urmând aceiași pași, ca să poată fi studiat și reparat. Notarea acestor pași e cea mai utilă parte dintr-un raport de bug.","also":["repro","a reproduce","reproduce","pași de reproducere","steps to reproduce"]},{"id":"severity","g":"test","word":"Gravitate","text":"Cât de grav e efectul unei probleme, de la un mic neajuns până la oprirea totală.","also":["nivel de gravitate","severitate","severity"]},{"id":"deploy","g":"change","word":"Deploy","text":"Copierea unei versiuni noi a software-ului pe calculatoarele care îl rulează, de exemplu o copie de test sau serviciul live."},{"id":"release","g":"change","word":"Lansare","text":"Un pachet de muncă terminată, cu nume, care merge live deodată, cu note scurte despre ce s-a schimbat. 🚀 Lansări scrie notele din cardurile terminate.","also":["lansări","release","versiune"]},{"id":"rollback","g":"change","word":"Rollback","text":"Întoarcerea la ultima versiune care a mers când una nouă face probleme. În AI-gile, butonul ↩ Revino adună într-o singură listă de verificare pașii de anulare notați la fiecare modificare.","also":["revenire","revenire la versiunea anterioară","anulare"]},{"id":"live","g":"change","word":"Live","text":"Versiunea reală pe care o folosesc oamenii, spre deosebire de o copie pentru încercări. Programatorii îi mai spun producție.","also":["producție","în producție"],"noTip":1},{"id":"change","g":"change","word":"Modificare","text":"O schimbare planificată la ceva pe care se bazează oamenii, scrisă dinainte: ce, de ce, riscul, când și cum o anulezi. Începe una cu 🔀 Propune o modificare.","also":["modificări","cerere de modificare","change request"],"noTip":1},{"id":"risk","g":"change","word":"Risc","text":"Ceva ce ar putea merge prost, notat după cât de probabil e și cât de grav ar fi. ⚠️ Riscuri le ține într-o singură listă, cu scorul cel mai mare primul, fiecare cu o dată la care te mai uiți o dată.","also":["riscuri","registrul riscurilor"]},{"id":"chgwin","g":"change","word":"Fereastră de modificări","text":"Momentele în care modificările pot merge live, de exemplu o seară liniștită de marți. În afara unei ferestre, un card de modificare nu poate fi terminat, decât dacă e o urgență.","also":["ferestre de modificări","change window"]},{"id":"gonogo","g":"change","word":"Go / no go","text":"O ultimă verificare chiar înainte ca o modificare să ajungă live: fiecare persoană care trebuie să aprobe spune Go sau No go. Merge mai departe doar dacă toți spun Go.","also":["go/no go","go-no-go"]},{"id":"approval","g":"change","word":"Aprobare","text":"Așteptarea unui da înainte să înceapă munca. Un card propus de un prieten, sau o modificare, așteaptă în ✅ Aprobări până îl aprobi sau îl respingi.","also":["aprobări"]},{"id":"quiettime","g":"change","word":"Perioadă de liniște","text":"O perioadă, de exemplu în timpul unui live stream, al unei demonstrații sau peste noapte, în care nimic nu ajunge live. Echipele continuă să lucreze și să testeze, dar punerea live așteaptă până se termină. În alte părți i se spune change freeze.","also":["perioade de liniște","înghețarea modificărilor","change freeze"]},{"id":"devops","g":"change","word":"DevOps","text":"O metodă de lucru în care cei care construiesc software și cei care îl rulează lucrează ca o singură echipă, cu multă automatizare, așa că schimbările ajung live des și în siguranță."},{"id":"cicd","g":"change","word":"CI/CD (integrare și livrare continuă)","text":"Modificările tuturor se îmbină des în versiunea principală și se verifică automat de fiecare dată (integrare continuă), așa că software-ul e mereu gata să ajungă live la apăsarea unui buton (livrare continuă).","also":["CI/CD","CI","CD","integrare continuă","livrare continuă","continuous integration","continuous delivery"]},{"id":"contdeploy","g":"change","word":"Implementare continuă","text":"Un pas mai departe de livrarea continuă: fiecare schimbare care trece verificările ajunge live singură, fără niciun buton de apăsat.","also":["implementare continuă","deployment continuu","continuous deployment"]},{"id":"pipeline","g":"change","word":"Pipeline","text":"Seria automată de pași prin care trece o schimbare pe drumul spre live, de exemplu build, test, apoi deploy.","also":["pipeline-uri","pipeline-ul","conductă"]},{"id":"environment","g":"change","word":"Mediu","text":"O copie separată a sistemului pentru un scop, de exemplu una în care construiești, una în care testezi și cea live.","also":["medii","mediul","environment"],"noTip":1},{"id":"devenv","g":"change","word":"Mediu de dezvoltare","text":"Copia în care lucrează un dezvoltator, adesea pe propriul calculator, unde dacă strici ceva nu pățește nimeni nimic.","also":["mediu dev","development environment","dev environment"]},{"id":"testenv","g":"change","word":"Mediu de test","text":"O copie separată a sistemului folosită doar pentru testare, ca să nu fie atins serviciul real.","also":["medii de test","test environment"]},{"id":"staging","g":"change","word":"Staging","text":"O ultimă copie configurată exact ca mediul live, pentru o verificare finală înainte ca o schimbare să ajungă live.","also":["mediu de staging","staging environment","preproducție"]},{"id":"artifact","g":"change","word":"Artefact de build","text":"Fișierul sau pachetul pe care îl produce un build, gata să fie păstrat, verificat sau pus live.","also":["artefacte de build","build artifact","artefact"]},{"id":"hotfix","g":"change","word":"Hotfix","text":"O remediere urgentă pusă live repede, în afara planului obișnuit, pentru că s-a stricat ceva important.","also":["hotfix-uri","hotfix-ul","remediere urgentă"]},{"id":"patch","g":"change","word":"Patch","text":"O actualizare mică ce repară un bug sau închide o breșă de securitate. Aplicarea rapidă a patch-urilor de securitate contează.","also":["patch-uri","patch-ul","petic","patch de securitate","security patch"]},{"id":"version","g":"change","word":"Număr de versiune","text":"O etichetă ca 2.4.1 care spune ce lansare ai. Adesea primul număr se schimbă la schimbări mari, iar ultimul la remedieri mici.","also":["numere de versiune","versiune","semantic versioning"]},{"id":"relnotes","g":"change","word":"Note de lansare","text":"O listă scurtă și simplă cu ce s-a schimbat într-o lansare, pentru cei care o folosesc, cu remedieri și limite cunoscute. Se mai numește changelog.","also":["changelog","change log","jurnal de modificări"]},{"id":"flag","g":"change","word":"Comutator de funcționalitate","text":"Un întrerupător pornit-oprit pentru o funcționalitate, ca munca nouă să poată ajunge live ascunsă și să fie pornită (sau oprită la loc) fără o lansare nouă.","also":["comutatoare de funcționalitate","feature flag","feature flags","feature toggle"]},{"id":"rollfwd","g":"change","word":"Roll forward","text":"A repara o lansare proastă scoțând repede o versiune nouă, corectată, în loc să te întorci la cea veche.","also":["roll forward","rolling forward","rolled forward","corectare prin versiune nouă"]},{"id":"canary","g":"change","word":"Lansare canary","text":"A pune o schimbare live întâi pentru un grup mic și pentru toți abia când pare în regulă. Numele vine de la canarii pe care minerii îi luau în subteran ca semnal de alarmă timpurie.","also":["lansări canary","canary release","canary"]},{"id":"bluegreen","g":"change","word":"Implementare blue-green","text":"A ține două copii ale sistemului live și a muta oamenii dintr-odată pe cea nouă, ca să poți reveni imediat dacă merge prost.","also":["blue-green","blue green deployment","albastru-verde"]},{"id":"zerodown","g":"change","word":"Implementare fără întrerupere","text":"A pune live o versiune nouă fără ca serviciul să se oprească vreodată pentru utilizatorii lui.","also":["fără întrerupere","zero downtime","zero-downtime"]},{"id":"chgenable","g":"change","word":"Gestionarea schimbărilor","text":"A ajuta schimbările să reușească: cântărești riscul, obții aprobarea potrivită și alegi un moment bun. Se mai numește change management.","also":["managementul schimbărilor","change management","change enablement"]},{"id":"cab","g":"change","word":"Comitet consultativ pentru schimbări (CAB)","text":"Un grup care se uită la schimbările importante și hotărăște dacă și când pot merge mai departe.","also":["CAB","change advisory board"]},{"id":"stdchange","g":"change","word":"Schimbare standard","text":"O schimbare cu risc mic, făcută de fiecare dată în același fel verificat, așa că e aprobată dinainte.","also":["schimbări standard","standard change"]},{"id":"normchange","g":"change","word":"Schimbare normală","text":"O schimbare care trebuie verificată și aprobată înainte să meargă mai departe.","also":["schimbări normale","normal change"]},{"id":"emergchange","g":"change","word":"Schimbare de urgență","text":"O schimbare care trebuie făcută pe loc ca să repare sau să prevină o problemă gravă, cu o aprobare mai rapidă pe măsură.","also":["schimbări de urgență","emergency change"]},{"id":"automation","g":"change","word":"Automatizare","text":"A pune calculatorul să facă singur o treabă repetată, ca să fie mai rapid și făcut la fel de fiecare dată.","also":["automatizări","automatizat","automation"],"noTip":1},{"id":"infra","g":"change","word":"Infrastructură","text":"Mașinile, rețelele și serviciile pe care rulează software-ul.","also":["infra","infrastructura"]},{"id":"iac","g":"change","word":"Infrastructură ca cod (IaC)","text":"A-ți descrie serverele și setările în fișiere ținute împreună cu codul, ca să poată fi reconstruite exact la fel de fiecare dată.","also":["IaC","infrastructure as code"]},{"id":"cloud","g":"change","word":"Cloud","text":"A închiria calculatoare, spațiu de stocare și servicii de la un furnizor mare, prin internet, în loc să ai tu mașinile.","also":["norul","cloud computing","în cloud"]},{"id":"provider","g":"change","word":"Furnizor de cloud","text":"O companie care închiriază putere de calcul prin internet, de exemplu Amazon Web Services (AWS), Microsoft Azure sau Google Cloud.","also":["furnizori de cloud","cloud provider"]},{"id":"hosting","g":"change","word":"Găzduire","text":"Locul unde trăiește și rulează aplicația sau site-ul tău, ca oamenii să ajungă la ele, de obicei închiriat de la o companie.","also":["hosting","găzduit","găzduirea"]},{"id":"domain","g":"change","word":"Nume de domeniu","text":"Adresa web pe care o scriu oamenii, de exemplu example.com. O închiriezi pe an, așa că trebuie reînnoită.","also":["nume de domenii","domeniu","domeniul","domain"]},{"id":"dns","g":"change","word":"DNS","text":"Prescurtarea de la domain name system (sistemul numelor de domenii): cartea de adrese a internetului, care transformă un nume ca example.com în adresa calculatorului potrivit.","also":["domain name system","sistemul numelor de domenii"]},{"id":"container","g":"change","word":"Container","text":"Un pachet sigilat care conține o aplicație și tot ce îi trebuie, ca să ruleze la fel pe orice calculator. Docker este cea mai cunoscută unealtă.","also":["containere","containerul","Docker"],"noTip":1},{"id":"vm","g":"change","word":"Mașină virtuală (VM)","text":"Un calculator simulat, care rulează în interiorul unuia adevărat, așa că o mașină mare poate juca rolul mai multora.","also":["VM","VM-uri","mașini virtuale","virtual machine"]},{"id":"serverless","g":"change","word":"Serverless","text":"A rula cod fără să te ocupi tu de vreun server: furnizorul îl rulează când e nevoie, iar tu plătești doar ce folosești."},{"id":"lb","g":"change","word":"Echilibrator de încărcare","text":"Ceva care împarte vizitatorii între mai multe servere, ca niciunul să nu fie copleșit.","also":["echilibratoare de încărcare","load balancer"]},{"id":"cache","g":"change","word":"Cache","text":"Un loc de stocare la îndemână pentru rezultate recente, ca același lucru să nu trebuiască adus sau calculat din nou. Golirea lui poate repara paginile care par vechi.","also":["cache-uri","cache-ul","memorie cache","caching","cached"]},{"id":"cdn","g":"change","word":"Rețea de livrare a conținutului (CDN)","text":"Un set de servere răspândite în lume care țin copii ale paginilor și imaginilor tale aproape de vizitatori, ca să se încarce repede.","also":["CDN","content delivery network"]},{"id":"migration","g":"change","word":"Migrare","text":"Mutarea datelor sau a sistemelor de la o configurație veche la una nouă, sau schimbarea atentă a felului în care e aranjată o bază de date.","also":["migrări","migrarea","migration","migrare de bază de date"]},{"id":"service","g":"run","word":"Serviciu","text":"Ceva construit de tine pe care se bazează oamenii, ca un site sau o aplicație, îngrijit ca să funcționeze în continuare. Bifează „Proiectul ăsta e un serviciu” și spune ce oferă, cine îl folosește și cine e de gardă.","also":["servicii"]},{"id":"uptimepct","g":"run","word":"Timp de funcționare","text":"Cât din timp funcționează un serviciu, de obicei ca procent. 99,9% tot înseamnă cam 43 de minute de oprire pe lună.","also":["uptime","procent de funcționare","uptime percentage"]},{"id":"uptime","g":"run","word":"Verificare de disponibilitate","text":"O verificare automată, la câteva minute, că serviciul tău încă răspunde. Dacă pică de mai multe ori la rând, AI-gile deschide singur un card de incident.","also":["uptime","verificări de disponibilitate","uptime checks"]},{"id":"statuspage","g":"run","word":"Pagină de status","text":"O pagină publică ce arată dacă un serviciu funcționează (verde, portocaliu sau roșu), cu ultima actualizare, ca cei care îl folosesc să poată verifica în loc să întrebe.","also":["pagini de status","status page"]},{"id":"desk","g":"run","word":"Service desk","text":"Locul unde ajung întrebările și semnalările de la oamenii care îți folosesc serviciul. AI-gile pune fiecare la cereri, incidente sau idei și îți spune când seamănă cu ceva deja semnalat.","also":["service desk-uri","birou","birou de asistență","help desk","helpdesk"]},{"id":"svcrequest","g":"run","word":"Cerere de serviciu","text":"Cineva cere ceva obișnuit, de exemplu un cont nou sau puțin ajutor, în loc să semnaleze că s-a stricat ceva. Își așteaptă rândul; un incident trece primul.","also":["cereri de serviciu","cerere"]},{"id":"incident","g":"run","word":"Incident","text":"Ceva care e stricat sau nu funcționează cum trebuie pentru cei care îl folosesc chiar acum, de exemplu site-ul căzut sau foarte lent. Un card de incident 🔥 sare peste rând: prioritatea e ca lucrurile să meargă din nou.","also":["incidente","pană","căzut"]},{"id":"major","g":"run","word":"Incident major","text":"Un incident mare: mulți oameni afectați, sau bani ori date în pericol. Un singur buton pune toate echipele pe el (roiul), îl trezește pe cel de gardă și cere o actualizare de status la fiecare 30 de minute.","also":["incidente majore","major incident"]},{"id":"oncall","g":"run","word":"De gardă","text":"Să fii cel care răspunde când se strică ceva, chiar și noaptea. Fiecare serviciu are un membru al echipei de gardă, care e trezit primul la incidentele lui.","also":["gardă","on call","on-call"]},{"id":"replyby","g":"run","word":"Termen de răspuns","text":"Cât poate aștepta un card un prim răspuns, de exemplu o oră pentru un incident. După aceea primește un ceas roșu, ca nimic să nu fie uitat pe tăcute. Se mai numește timp de răspuns țintă.","also":["termene de răspuns","ore de răspuns","timp de răspuns țintă"]},{"id":"postmortem","g":"run","word":"Post-mortem","text":"O privire scurtă înapoi după un incident: ce s-a întâmplat, ce a ajutat și ce trebuie schimbat, fără să dai vina pe cineva. Un incident nu poate fi închis fără el.","also":["post-mortemuri","postmortem","analiză după incident"]},{"id":"problem","g":"run","word":"Problemă","text":"Cauza ascunsă din spatele unuia sau mai multor incidente. Un card de 🧩 problemă adună incidentele care tot revin, ca să fie găsită cauza și reparată definitiv.","also":["probleme"],"noTip":1},{"id":"rootcause","g":"run","word":"Cauza principală","text":"Motivul real pentru care s-a stricat ceva, nu doar ce ai văzut mergând prost. Repară cauza principală și incidentul nu mai revine.","also":["cauze principale","cauza rădăcină","root cause"]},{"id":"workaround","g":"run","word":"Soluție provizorie","text":"Un mod de a ține lucrurile funcționale până e gata reparația adevărată, de exemplu repornirea a ceva când se blochează. E scrisă pe cardul problemei, ca nimeni să nu trebuiască s-o descopere din nou.","also":["soluții provizorii","workaround","ocolire"]},{"id":"knownerror","g":"run","word":"Eroare cunoscută","text":"O problemă a cărei cauză e înțeleasă, dar care nu e reparată încă, de obicei cu o soluție ocolitoare notată. 🧩 Erori cunoscute le listează, ca toată lumea să folosească soluția ocolitoare în loc să sape din nou.","also":["erori cunoscute","known error"]},{"id":"runbook","g":"run","word":"Runbook","text":"Instrucțiuni pas cu pas pentru a rezolva un tip cunoscut de problemă, ca să se facă la fel, repede, de fiecare dată. După un incident mare, echipa poate propune unul pentru care să dai OK.","also":["runbookuri","procedură","instrucțiuni de operare"]},{"id":"ci","g":"run","word":"Element de configurare","text":"Un lucru de care depinde serviciul tău, de exemplu un server, un domeniu, un certificat, o cheie sau un furnizor. 🗂️ Elemente de configurare le listează pe fiecare serviciu, ca să vezi ce afectează un incident și ce trebuie reînnoit sau salvat într-un backup.","also":["elemente de configurare"]},{"id":"expiry","g":"run","word":"Dată de expirare","text":"Data la care ceva se oprește dacă nu e reînnoit, de exemplu certificatul de securitate al unui site sau adresa lui web. AI-gile urmărește aceste date și face câte un card de reînnoire pentru fiecare cu 30 de zile înainte, ca nimic să nu se oprească pe neașteptate.","also":["date de expirare","expirare","urmărirea expirării"]},{"id":"backup","g":"run","word":"Backup","text":"O copie salvată mai devreme a datelor tale, la care să revii dacă se pierde sau se strică ceva. AI-gile face zilnic un backup al panourilor tale.","also":["backupuri","copie de rezervă","copii de rezervă"]},{"id":"restore","g":"run","word":"Restaurare","text":"Aducerea datelor înapoi dintr-un backup. Un backup contează cu adevărat doar când știi că poate fi restaurat, așa că merită încercat din când în când.","also":["restaurat","restaurează","restore"]},{"id":"svcreview","g":"run","word":"Revizuirea serviciului","text":"O privire înapoi la o lună dintr-un serviciu: incidente deschise și rezolvate, cât de repede au primit oamenii răspuns, disponibilitate și tokeni folosiți. Revizuirea lunară arată asta pentru fiecare serviciu.","also":["revizuiri ale serviciului","revizuire lunară","revizuiri lunare"]},{"id":"accessreview","g":"run","word":"Revizuirea accesului","text":"O verificare la fiecare 90 de zile a cine mai poate intra: linkuri de partajare, rolurile prietenilor și parolele și cheile salvate. Păstrezi sau scoți fiecare, ca accesul vechi să nu rămână.","also":["revizuiri ale accesului"]},{"id":"improvements","g":"run","word":"Lista de îmbunătățiri","text":"Tot ce a hotărât echipa să facă mai bine, într-un singur loc: sugestii din retro, acțiuni din revizii și reparații de probleme, fiecare cu statusul ei. O găsești la 📈 Îmbunătățiri.","also":["liste de îmbunătățiri","îmbunătățiri"]},{"id":"tokencap","g":"run","word":"Plafon de tokeni","text":"O limită lunară pentru tokenii pe care îi pot folosi agenții unui serviciu. La 80% primești un avertisment; la 100% munca lor din fundal așteaptă până luna viitoare sau până ridici plafonul.","also":["plafoane de tokeni","plafon lunar de tokeni"]},{"id":"svcmgmt","g":"run","word":"Managementul serviciilor","text":"Tot ce e nevoie ca un serviciu să rămână util și funcțional, zi de zi, pentru oamenii care se bazează pe el.","also":["gestionarea serviciilor","service management"]},{"id":"itil","g":"run","word":"ITIL","text":"Un ghid larg folosit pentru buna gestionare a serviciilor, care acoperă lucruri ca incidente, probleme și schimbări. Numele însemna cândva IT Infrastructure Library."},{"id":"itsm","g":"run","word":"Managementul serviciilor IT (ITSM)","text":"A gestiona tehnologia ca pe un serviciu pentru oameni, cu modalități clare de a trata cereri, incidente, schimbări și îmbunătățiri.","also":["ITSM","IT service management"]},{"id":"managed","g":"run","word":"Serviciu gestionat","text":"Un serviciu pe care îl operează și îl întreține altcineva pentru tine, pe baza unui acord despre cât de bine trebuie să funcționeze.","also":["servicii gestionate","managed service","serviciu administrat"]},{"id":"svcowner","g":"run","word":"Responsabilul serviciului","text":"Persoana care răspunde de un serviciu în întregime: cât de bine merge, cât costă și cum se îmbunătățește.","also":["responsabili de serviciu","proprietarul serviciului","service owner"]},{"id":"sla","g":"run","word":"Acord privind nivelul serviciului (SLA)","text":"O promisiune scrisă către clienți despre cât de bine va funcționa un serviciu, de exemplu „disponibil 99,9% din timp” sau „răspuns în maximum o oră”, adesea cu returnarea banilor dacă nu se respectă.","also":["SLA","SLA-uri","service level agreement"]},{"id":"slo","g":"run","word":"Obiectiv de nivel al serviciului (SLO)","text":"Ținta proprie a echipei pentru cât de bine ar trebui să funcționeze un serviciu într-o perioadă, de obicei stabilită un pic mai strict decât SLA-ul, ca să fie pe siguranță.","also":["SLO","SLO-uri"]},{"id":"sli","g":"run","word":"Indicator de nivel al serviciului (SLI)","text":"Măsurătoarea reală pe care o compari cu o țintă, de exemplu procentul de vizite la care pagina s-a încărcat bine.","also":["SLI","SLI-uri"]},{"id":"availability","g":"run","word":"Disponibilitate","text":"Dacă oamenii pot folosi un serviciu atunci când au nevoie, adesea măsurată ca timp de funcționare.","also":["disponibilitate ridicată","high availability","availability"]},{"id":"downtime","g":"run","word":"Timp de nefuncționare","text":"Timpul în care un serviciu nu funcționează sau e oprit, planificat sau nu.","also":["oprire","downtime","timp de oprire"]},{"id":"errorbudget","g":"run","word":"Buget de erori","text":"Cantitatea mică de eșecuri pe care o permite ținta ta de fiabilitate. Cât timp mai rămâne din ea, poți risca cu schimbări; când s-a consumat, încetinești.","also":["bugete de erori","error budget"]},{"id":"outage","g":"run","word":"Întrerupere","text":"O perioadă în care un serviciu e căzut sau grav stricat pentru utilizatorii lui.","also":["întreruperi","cădere","outage"]},{"id":"degraded","g":"run","word":"Funcționare degradată","text":"Funcționează, dar prost: încet, sau cu unele părți care nu merg.","also":["serviciu degradat","degraded","degraded service"]},{"id":"monitoring","g":"run","word":"Monitorizare","text":"A urmări un serviciu automat tot timpul, ca problemele să fie observate, ideal înainte să le simtă utilizatorii.","also":["monitorizat","monitoring","supraveghere"]},{"id":"observability","g":"run","word":"Observabilitate","text":"Cât de bine poți înțelege din afară ce se întâmplă în interiorul unui sistem, folosind jurnalele, numerele și urmele lui.","also":["observabilitatea","observability","o11y"]},{"id":"log","g":"run","word":"Jurnal","text":"Un jurnal continuu pe care îl ține un program despre ce face, folosit ca să afli ce a mers prost.","also":["jurnale","log","log-uri","logging"],"noTip":1},{"id":"trace","g":"run","word":"Urmă (trace)","text":"O înregistrare a drumului pe care îl parcurge o cerere prin diferitele părți ale unui sistem, pas cu pas, care arată unde a încetinit.","also":["urme","trace","trace-uri","tracing"]},{"id":"latency","g":"run","word":"Latență","text":"Cât durează până răspunde ceva, de exemplu așteptarea dintre clic și apariția paginii.","also":["latența"]},{"id":"alert","g":"run","word":"Alertă","text":"Un mesaj automat care anunță că ceva cere atenție, de exemplu că site-ul nu răspunde.","also":["alerte","alertă","alerting","alertare"],"noTip":1},{"id":"alertfatigue","g":"run","word":"Oboseala de alerte","text":"Când sunt atât de multe alerte încât oamenii încep să le ignore, inclusiv pe cele importante.","also":["oboseală de alerte","alert fatigue","alarm fatigue"]},{"id":"dashboard","g":"run","word":"Panou de control","text":"Un ecran care arată dintr-o privire cele mai importante numere și stări.","also":["panouri de control","dashboard","dashboard-uri"],"noTip":1},{"id":"paging","g":"run","word":"Apelare de urgență","text":"A suna sau a trezi de urgență persoana de gardă din cauza unei probleme.","also":["paging","apelat","a apela de urgență"]},{"id":"escalation","g":"run","word":"Escaladare","text":"Implicarea cuiva cu mai multă pricepere sau autoritate când o problemă nu poate fi rezolvată la nivelul curent sau nu destul de repede.","also":["escaladări","a escalada","escalation"]},{"id":"triage","g":"run","word":"Triaj","text":"A sorta repede problemele primite după cât sunt de urgente și de importante, ca cea mai gravă să fie tratată prima.","also":["triere","triage"]},{"id":"impact","g":"run","word":"Impact","text":"Cât de mult afectează ceva oamenii: câți și cât de grav.","noTip":1},{"id":"urgency","g":"run","word":"Urgență","text":"Cât de repede trebuie tratat ceva. Impactul și urgența împreună stabilesc prioritatea.","noTip":1},{"id":"plevels","g":"run","word":"Niveluri de prioritate (P1, P2…)","text":"Etichete pentru cât de urgentă e o problemă. P1 e cea mai gravă și cere acțiune imediată.","also":["P1","P2","P3","P4"]},{"id":"queue","g":"run","word":"Coada de tichete","text":"Lista cererilor și incidentelor care așteaptă să fie preluate.","also":["cozi de tichete","ticket queue"]},{"id":"tiers","g":"run","word":"Prima linie și a doua linie","text":"Niveluri de suport: prima linie răspunde la apel și rezolvă lucrurile simple; a doua linie are cunoștințe mai adânci pentru cele mai grele. Se mai numesc nivel 1 și nivel 2.","also":["prima linie","a doua linie","suport de prima linie","nivel 1","nivel 2","tier 1","tier 2"]},{"id":"ic","g":"run","word":"Coordonatorul incidentului","text":"Singura persoană care conduce răspunsul la un incident, ca toată lumea să știe cine hotărăște și cine ce face.","also":["coordonatori de incident","incident commander"]},{"id":"responsetime","g":"run","word":"Timp de răspuns","text":"Cât durează până când cineva preia prima oară o cerere sau un incident.","also":["timpi de răspuns","response time"]},{"id":"resolution","g":"run","word":"Timp de rezolvare","text":"Cât durează să se rezolve complet o cerere sau un incident, de la raportare până la remediere.","also":["timpi de rezolvare","resolution time","time to resolve"]},{"id":"mttr","g":"run","word":"Timp mediu de recuperare (MTTR)","text":"În medie, cât durează până când un serviciu funcționează din nou după ce s-a stricat. MTTR poate însemna lucruri ușor diferite, așa că spune ce măsori.","also":["MTTR","mean time to recover","mean time to restore"]},{"id":"mtbf","g":"run","word":"Timp mediu între defecțiuni (MTBF)","text":"În medie, cât timp rulează un serviciu până se strică ceva.","also":["MTBF","mean time between failures"]},{"id":"cmdb","g":"run","word":"Bază de date de configurare (CMDB)","text":"Lista tuturor elementelor tale de configurare și a legăturilor dintre ele, ca să vezi ce depinde de ce.","also":["CMDB","configuration management database"]},{"id":"asset","g":"run","word":"Activ","text":"Orice lucru de valoare pe care îl deții sau pentru care plătești ca să rulezi serviciul, de exemplu un laptop, o licență de software sau un domeniu.","also":["active","activul","asset"],"noTip":1},{"id":"capplan","g":"run","word":"Planificarea capacității","text":"A te asigura că va fi destulă putere de calcul, spațiu de stocare și oameni pentru ce urmează.","also":["plan de capacitate","capacity planning","capacity plan"]},{"id":"scaling","g":"run","word":"Scalare","text":"A face față mai multor utilizatori dând unei mașini mai multă putere (scalare pe verticală) sau adăugând mai multe mașini (scalare pe orizontală).","also":["a scala","scale up","scale out","scaling up","scaling out","scaling"]},{"id":"bcp","g":"run","word":"Continuitatea afacerii","text":"Planuri pentru ca lucrurile importante să meargă mai departe când se întâmplă ceva grav, de exemplu pierderea unui birou, a unui furnizor esențial sau a calculatoarelor.","also":["planul de continuitate a afacerii","business continuity","business continuity plan"]},{"id":"dr","g":"run","word":"Recuperare după dezastru (DR)","text":"Planul și uneltele pentru a readuce un serviciu după ceva grav, de exemplu pierderea unui întreg centru de date.","also":["DR","disaster recovery","refacere după dezastru"]},{"id":"rto","g":"run","word":"Timp țintă de recuperare (RTO)","text":"Timpul maxim cât poate sta un serviciu oprit după un dezastru, până când trebuie să funcționeze din nou.","also":["RTO","recovery time objective"]},{"id":"rpo","g":"run","word":"Punct țintă de recuperare (RPO)","text":"Câte date recente îți permiți să pierzi, măsurat în timp. Un RPO de o oră înseamnă copii de siguranță cel puțin la fiecare oră.","also":["RPO","recovery point objective"]},{"id":"redundancy","g":"run","word":"Redundanță","text":"A avea rezerve gata, de exemplu un al doilea server, ca o defecțiune să nu oprească serviciul.","also":["redundanță","redundancy"]},{"id":"failover","g":"run","word":"Trecere pe rezervă","text":"Trecerea automată pe un sistem de rezervă când cel obișnuit cedează.","also":["failover","fail over","comutare automată"]},{"id":"spof","g":"run","word":"Punct unic de defectare","text":"O singură parte care trage totul după ea când se strică, pentru că nu există rezervă.","also":["puncte unice de defectare","single point of failure","SPOF"]},{"id":"maintwin","g":"run","word":"Fereastră de mentenanță","text":"Un moment planificat în care un serviciu poate fi oprit sau încetinit pentru întreținere, anunțat din timp utilizatorilor.","also":["ferestre de mentenanță","mentenanță planificată","maintenance window"]},{"id":"handover","g":"run","word":"Predare","text":"Trecerea muncii, a cunoștințelor și a răspunderii la altă persoană sau echipă, ca nimic să nu se piardă.","also":["predări","predare-primire","handover"]},{"id":"kb","g":"run","word":"Bază de cunoștințe","text":"O colecție de articole de ajutor și răspunsuri, pentru utilizatori și pentru echipă.","also":["baze de cunoștințe","knowledge base"]},{"id":"csat","g":"run","word":"Satisfacția clienților (CSAT)","text":"Un scor dat de utilizatori care spune cât de mulțumiți au fost, adesea cerut după ce o cerere e închisă.","also":["CSAT","customer satisfaction","satisfacția utilizatorilor"]},{"id":"supplier","g":"run","word":"Furnizor","text":"O companie din afară pe care te bazezi, de exemplu furnizorul tău de găzduire. Se mai numește vendor sau terț.","also":["furnizori","vendor","vendori","terț","terți","third party"],"noTip":1},{"id":"retire","g":"run","word":"Retragerea unui serviciu","text":"A opri un serviciu pentru totdeauna, în siguranță: anunți utilizatorii, tratezi datele și accesul și oprești costurile.","also":["scoaterea din uz a unui serviciu","retiring a service"]},{"id":"eol","g":"run","word":"Sfârșit de viață (EOL)","text":"Când un produs nu mai primește actualizări sau suport de la producătorul lui, așa că ar trebui înlocuit.","also":["EOL","end of life","end-of-life"]},{"id":"cybersec","g":"sec","word":"Securitate cibernetică","text":"Protejarea sistemelor și a datelor ca să nu fie sparte, furate sau deteriorate.","also":["securitate cibernetică","cybersecurity","cyber security","securitate informatică"]},{"id":"authn","g":"sec","word":"Autentificare","text":"A verifica cine este cineva, de obicei cu o parolă sau un cod. Adesea prescurtată authn.","also":["authn","authentication"]},{"id":"authz","g":"sec","word":"Autorizare","text":"A verifica ce are voie să facă cineva după ce știi cine este. Adesea prescurtată authz.","also":["authz","authorization","authorisation"]},{"id":"mfa","g":"sec","word":"Autentificare cu mai mulți factori (MFA)","text":"A te conecta cu două sau mai multe dovezi, de exemplu o parolă plus un cod pe telefon. Se mai numește autentificare în doi pași (2FA).","also":["MFA","2FA","doi factori","autentificare în doi pași","two-factor","two-factor authentication"]},{"id":"sso","g":"sec","word":"Autentificare unică (SSO)","text":"Te conectezi o singură dată și intri în mai multe sisteme, de exemplu când folosești peste tot contul de la serviciu.","also":["SSO","single sign-on"]},{"id":"pwmgr","g":"sec","word":"Manager de parole","text":"O aplicație care creează parole puternice și le ține minte în locul tău.","also":["manageri de parole","password manager"]},{"id":"secret","g":"sec","word":"Secret","text":"O parolă, o cheie sau alt cod privat pe care un program îl folosește ca să intre undeva. Nu trebuie niciodată dat altora sau scris în cod.","also":["secrete","secrets","secret"],"noTip":1},{"id":"apikey","g":"sec","word":"Cheie API","text":"Un cod secret care îi dă voie unui program să folosească API-ul altui serviciu și arată cine îl folosește (și îl plătește).","also":["chei API","API key"]},{"id":"accesstoken","g":"sec","word":"Token de acces","text":"Un permis temporar care dovedește că un program are voie să intre, ca să nu-ți mai trebuiască parola de fiecare dată. Nu e același lucru cu un token AI.","also":["tokeni de acces","access token"]},{"id":"encryption","g":"sec","word":"Criptare","text":"Codificarea informațiilor astfel încât doar cine are cheia potrivită să le poată citi.","also":["criptat","a cripta","encryption","encrypted"]},{"id":"https","g":"sec","word":"HTTPS","text":"Modul sigur în care circulă paginile web, semnalat de lacătul din browser, ca nimeni aflat pe traseu să nu le poată citi sau schimba."},{"id":"cert","g":"sec","word":"Certificat SSL/TLS","text":"O carte de identitate digitală prin care un site își dovedește identitatea și poate folosi HTTPS. Expiră, așa că trebuie reînnoită.","also":["certificat TLS","certificat SSL","certificat","certificate","certificate SSL"]},{"id":"permissions","g":"sec","word":"Permisiuni","text":"Regulile despre cine are voie să vadă sau să schimbe ce.","also":["permisiune","permissions"],"noTip":1},{"id":"leastpriv","g":"sec","word":"Privilegiul minim","text":"A da fiecărei persoane sau fiecărui program doar accesul de care chiar are nevoie, doar cât timp are nevoie.","also":["cel mai mic privilegiu","principiul privilegiului minim","least privilege"]},{"id":"rbac","g":"sec","word":"Control al accesului pe roluri (RBAC)","text":"A da acces în funcție de rol, de exemplu cititor sau editor, nu persoană cu persoană.","also":["RBAC","acces pe bază de roluri","role-based access control"]},{"id":"vuln","g":"sec","word":"Vulnerabilitate","text":"O slăbiciune pe care cineva ar putea-o folosi ca să pătrundă într-un sistem sau să facă rău.","also":["vulnerabilități","vulnerabilitatea","vulnerability"]},{"id":"zeroday","g":"sec","word":"Zero-day","text":"O slăbiciune pe care atacatorii o cunosc înainte ca producătorii să fi avut vreme s-o repare.","also":["zero-day","zero-days","zero day","vulnerabilitate zero-day"]},{"id":"malware","g":"sec","word":"Malware","text":"Software dăunător, de exemplu viruși, făcut să strice, să spioneze sau să fure.","also":["software rău intenționat"]},{"id":"ransomware","g":"sec","word":"Ransomware","text":"Malware care îți blochează fișierele și cere bani ca să le deblocheze. Copiile de siguranță bune sunt cea mai bună apărare.","also":["atac ransomware","virus care cere răscumpărare"]},{"id":"phishing","g":"sec","word":"Phishing","text":"Mesaje false care încearcă să te păcălească să-ți dai parolele sau banii sau să deschizi ceva dăunător.","also":["e-mail de phishing","e-mailuri de phishing","înșelăciune prin e-mail"]},{"id":"socialeng","g":"sec","word":"Inginerie socială","text":"A păcăli oamenii, nu calculatoarele, ca să dea acces, de exemplu un apel fals de la „suportul IT”."},{"id":"firewall","g":"sec","word":"Firewall","text":"Un paznic care hotărăște ce trafic de rețea are voie să intre sau să iasă.","also":["firewall-uri","zid de protecție","firewall-ul"]},{"id":"vpn","g":"sec","word":"VPN","text":"Prescurtarea de la virtual private network (rețea privată virtuală): o legătură privată, criptată, prin internet, folosită adesea ca să ajungi în siguranță la sistemele de la serviciu.","also":["rețea privată virtuală","virtual private network"]},{"id":"ddos","g":"sec","word":"Refuz de serviciu (DoS, DDoS)","text":"Inundarea unui serviciu cu atât de mult trafic fals încât oamenii adevărați nu-l mai pot folosi. DDoS înseamnă că vine de la multe calculatoare deodată.","also":["DoS","DDoS","denial of service","atac DDoS","DDoS attack"]},{"id":"pentest","g":"sec","word":"Test de penetrare (pen test)","text":"Angajarea unor experți de încredere care încearcă să spargă sistemul, ca slăbiciunile să fie găsite înainte să le găsească atacatorii adevărați.","also":["pen test","pentest","pen testing","penetration testing","testare de penetrare"]},{"id":"audit","g":"sec","word":"Audit de securitate","text":"O verificare atentă a cât de bine e protejat ceva, pe baza unei liste de bune practici.","also":["audituri de securitate","security audit"]},{"id":"threatmodel","g":"sec","word":"Modelarea amenințărilor","text":"A te gândi cine ar putea ataca ceva, cum, și ce ai face ca să-i oprești.","also":["model de amenințări","threat model","threat modelling","threat modeling"]},{"id":"breach","g":"sec","word":"Încălcarea securității datelor","text":"Când informații private ajung la oameni care n-ar trebui să le aibă, sau sunt pierdute ori schimbate fără permisiune.","also":["încălcări ale securității datelor","scurgere de date","data breach"]},{"id":"pii","g":"sec","word":"Date personale","text":"Orice informație despre o persoană care poate fi identificată, de exemplu un nume, o adresă de e-mail sau o locație. Se mai numesc PII.","also":["PII","date cu caracter personal","personally identifiable information"]},{"id":"gdpr","g":"sec","word":"GDPR","text":"Legea europeană despre datele personale (Regatul Unit are propria versiune): colectezi doar ce îți trebuie, le ții în siguranță și îi lași pe oameni să le vadă sau să le șteargă pe ale lor.","also":["RGPD","Regulamentul general privind protecția datelor","General Data Protection Regulation"]},{"id":"dataprot","g":"sec","word":"Protecția datelor","text":"A avea grijă cum trebuie de datele personale, în limitele legii.","also":["legea protecției datelor","data protection"]},{"id":"privacypolicy","g":"sec","word":"Politică de confidențialitate","text":"O pagină publică ce spune ce date personale colectezi, de ce și ce faci cu ele.","also":["declarație de confidențialitate","notă de informare","privacy policy"]},{"id":"consent","g":"sec","word":"Consimțământ","text":"Un „da” clar și liber al unei persoane ca datele ei să fie folosite într-un anumit fel. Îl poate retrage oricând.","also":["acord","opt-in","consent"],"noTip":1},{"id":"cookie","g":"sec","word":"Cookie","text":"Un fișier mic pe care un site îl salvează în browserul tău ca să țină minte lucruri, de exemplu faptul că te-ai conectat. Unele cer întâi consimțământul tău.","also":["cookie-uri","cookie-ul","cookies"],"noTip":1},{"id":"minimisation","g":"sec","word":"Reducerea la minimum a datelor","text":"A colecta și a păstra doar datele personale de care chiar ai nevoie pentru treaba respectivă.","also":["minimizarea datelor","data minimisation","data minimization"]},{"id":"retention","g":"sec","word":"Păstrarea datelor","text":"Cât timp sunt păstrate datele înainte să fie șterse. Să nu le ții mai mult decât trebuie e mai sigur și adesea cerut de lege.","also":["perioadă de păstrare","data retention","retention period"]},{"id":"anon","g":"sec","word":"Anonimizare","text":"Schimbarea datelor astfel încât, în mod rezonabil, nimeni să nu mai poată fi identificat din ele.","also":["anonimizat","date anonime","anonymisation"]},{"id":"pseudo","g":"sec","word":"Pseudonimizare","text":"Înlocuirea numelor și a altor detalii cu coduri, cu o cheie ținută separat prin care se pot reface legăturile. Rămân tot date personale.","also":["pseudonimizat","pseudonymisation"]},{"id":"dpa","g":"sec","word":"Acord de prelucrare a datelor (DPA)","text":"Un contract care spune cum are voie un furnizor să prelucreze datele personale în numele tău.","also":["DPA","data processing agreement"]},{"id":"dpia","g":"sec","word":"Evaluarea impactului asupra protecției datelor (DPIA)","text":"O analiză atentă, înainte de a începe, a felului în care un plan de folosire a datelor personale ar putea afecta oamenii și cum se reduc riscurile.","also":["DPIA","data protection impact assessment"]},{"id":"auditlog","g":"sec","word":"Jurnal de audit","text":"O înregistrare a cine a făcut ce și când, ca acțiunile să poată fi verificate mai târziu.","also":["jurnale de audit","audit log","audit trail"]},{"id":"compliance","g":"sec","word":"Conformitate","text":"A respecta legile, regulile și standardele care se aplică în cazul tău și a putea dovedi că le respecți.","also":["conform","compliance"]},{"id":"iso","g":"sec","word":"ISO 27001","text":"Un standard internațional bine cunoscut pentru gestionarea securității informațiilor. Companiile se pot certifica după el.","also":["ISO/IEC 27001"]},{"id":"soc","g":"sec","word":"SOC 2","text":"Un raport american, verificat de auditori externi, care arată că o companie are grijă cum trebuie de datele clienților.","also":["SOC2"]},{"id":"agent","g":"ai","word":"Agent","text":"Un AI care lucrează singur la o sarcină: citește codul, face schimbări, rulează verificări și raportează. Munca lui tot se verifică.","also":["agenți","agentul","agentului"]},{"id":"token","g":"ai","word":"Token","text":"Bucățile mici de text pe care le citește și le scrie un AI, fiecare cam trei sferturi dintr-un cuvânt. Folosirea AI se numără în tokeni, deci mai puțini tokeni lasă mai mult din planul tău.","also":["tokeni","tokenii","tokenilor"]},{"id":"hook","g":"ai","word":"Hook","text":"O comandă mică ce rulează singură într-un moment stabilit, de exemplu când pornește o sesiune AI, ca echipa să audă comentariile tale.","also":["hook-uri","hook-ul","hook-urile"]},{"id":"ai","g":"ai","word":"Inteligență artificială (AI)","text":"Sisteme de calcul care fac lucruri pentru care de obicei credem că e nevoie de un om, de exemplu să scrie, să răspundă la întrebări sau să recunoască imagini.","also":["AI","IA","inteligență artificială","artificial intelligence"],"noTip":1},{"id":"ml","g":"ai","word":"Învățare automată (ML)","text":"O metodă prin care calculatoarele învață tipare din multe exemple, în loc să primească reguli exacte.","also":["ML","învățare automată","machine learning"]},{"id":"model","g":"ai","word":"Model","text":"„Creierul” antrenat al unui sistem AI, construit învățând dintr-un număr uriaș de exemple. Modelele diferă ca pricepere, viteză și preț.","also":["modele","modelul","model AI","AI model"],"noTip":1},{"id":"llm","g":"ai","word":"Model lingvistic mare (LLM)","text":"Un model AI antrenat pe cantități uriașe de text, așa că poate înțelege și scrie text.","also":["LLM","LLM-uri","large language model"]},{"id":"genai","g":"ai","word":"AI generativ","text":"AI care creează lucruri noi, de exemplu text, imagini sau cod, nu doar le sortează sau le recunoaște.","also":["AI generativă","GenAI"]},{"id":"chatbot","g":"ai","word":"Chatbot","text":"Un program cu care conversezi în limbaj obișnuit, în scris sau prin voce.","also":["chatbot-uri","chatbot-ul","robot de conversație"]},{"id":"prompt","g":"ai","word":"Prompt","text":"Ce îi dai unui AI: întrebarea sau instrucțiunile tale, plus orice materiale îi oferi. Prompturile mai clare dau de obicei răspunsuri mai bune.","also":["prompturi","promptul","instrucțiune"]},{"id":"prompteng","g":"ai","word":"Prompt engineering","text":"Priceperea de a scrie prompturi care dau rezultate de încredere și utile.","also":["ingineria prompturilor"]},{"id":"sysprompt","g":"ai","word":"Prompt de sistem","text":"Instrucțiuni de fundal pe care un AI le primește înainte să înceapă conversația, care îi stabilesc rolul și regulile. Cântăresc mai mult decât ce scrii tu.","also":["prompturi de sistem","system prompt","system instruction","instrucțiuni de sistem"]},{"id":"context","g":"ai","word":"Context","text":"Tot ce poate vedea AI-ul cât lucrează: instrucțiunile, mesajele tale, fișierele citite și răspunsurile de mai devreme.","noTip":1},{"id":"ctxwin","g":"ai","word":"Fereastră de context","text":"Cât poate ține un AI minte deodată, măsurat în tokeni. Dincolo de asta, părțile mai vechi sunt lăsate deoparte sau rezumate.","also":["ferestre de context","fereastra de context","context window"]},{"id":"session","g":"ai","word":"Sesiune","text":"O conversație de lucru cu un AI, de la început până la sfârșit. O sesiune nouă începe cu memoria curată.","also":["sesiuni","sesiunea","session"],"noTip":1},{"id":"memory","g":"ai","word":"Memorie","text":"Notițe pe care un AI le păstrează între sesiuni, ca să-ți țină minte preferințele și deciziile de până acum.","noTip":1},{"id":"hallucination","g":"ai","word":"Halucinație","text":"Când un AI spune ceva care sună foarte convingător, dar e inventat sau greșit. Verifică faptele importante.","also":["halucinații","a halucina","halucinează","hallucination"]},{"id":"training","g":"ai","word":"Antrenare","text":"Învățarea unui model arătându-i un număr uriaș de exemple, înainte să-l folosească cineva.","also":["antrenat","antrenament","training","trained"],"noTip":1},{"id":"trainingdata","g":"ai","word":"Date de antrenare","text":"Exemplele din care a învățat un model. Cunoștințele lui se opresc la data la care au fost colectate datele.","also":["set de antrenare","training data","training set"]},{"id":"cutoff","g":"ai","word":"Limita cunoștințelor","text":"Data la care se termină cunoștințele încorporate ale unui AI. Nu știe de lucrurile de după, decât dacă le caută.","also":["data limită a cunoștințelor","knowledge cutoff","training cutoff"]},{"id":"finetune","g":"ai","word":"Reglaj fin","text":"Antrenare suplimentară a unui model existent pe exemplele tale, ca să devină mai bun la o anumită treabă.","also":["fine-tuning","fine-tune","fine-tuned","fine tuning","ajustare fină"]},{"id":"inference","g":"ai","word":"Inferență","text":"Un model AI folosit efectiv ca să răspundă la ceva, spre deosebire de antrenarea lui.","also":["inferența","inference","model inference"]},{"id":"tooluse","g":"ai","word":"Folosirea uneltelor","text":"Un AI care poate face lucruri, nu doar să vorbească: rulează comenzi, citește fișiere sau caută pe web, prin uneltele pe care i le dă aplicația.","also":["utilizarea uneltelor","tool use","tool calling","tool call","tool calls"]},{"id":"subagent","g":"ai","word":"Subagent","text":"Un AI ajutor căruia un AI principal îi dă o treabă mai mică și de la care primește rezultatul.","also":["subagenți","subagentul","subagents","sub-agent"]},{"id":"multiagent","g":"ai","word":"Multi-agent","text":"Mai multe AI-uri care lucrează împreună la o singură treabă, fiecare cu partea lui, ca o echipă mică.","also":["mai mulți agenți","multi-agent system","sistem multi-agent"]},{"id":"autonomy","g":"ai","word":"Autonomie","text":"Cât de mult are voie un AI să facă singur înainte să trebuiască să întrebe un om.","also":["autonom","autonomia","autonomy"]},{"id":"hitl","g":"ai","word":"Omul în buclă","text":"A ține un om implicat ca să verifice sau să aprobe ce face AI-ul în punctele cheie. În AI-gile, acela ești tu.","also":["om în buclă","human in the loop","human-in-the-loop","HITL"]},{"id":"guardrails","g":"ai","word":"Limite de siguranță (guardrails)","text":"Limite și verificări care țin în siguranță acțiunile unui AI, de exemplu nevoia unei aprobări înainte ca ceva să ajungă live. Reduc riscul de greșeli, dar nu le exclud.","also":["limită de siguranță","guardrails","guardrail","balustrade de siguranță"]},{"id":"rag","g":"ai","word":"Generare augmentată prin regăsire (RAG)","text":"A lăsa un AI să caute în propriile tale documente înainte să răspundă, ca răspunsurile lui să se sprijine pe faptele tale.","also":["RAG","retrieval-augmented generation","retrieval augmented generation"]},{"id":"embedding","g":"ai","word":"Embedding","text":"A transforma textul într-o listă de numere care îi surprinde sensul, ca un calculator să poată găsi lucruri cu sensuri asemănătoare.","also":["embeddings","embedding-uri","reprezentare vectorială"]},{"id":"vectordb","g":"ai","word":"Bază de date vectorială","text":"O bază de date făcută pentru căutarea în acele liste de numere (embedding-uri), ca să găsească materiale cu sens asemănător.","also":["baze de date vectoriale","vector database","vector store"]},{"id":"mcp","g":"ai","word":"Model Context Protocol (MCP)","text":"Un mod comun de a lega unelte și surse de date la aplicații AI, ca un AI să le poată folosi.","also":["MCP"]},{"id":"temperature","g":"ai","word":"Temperatură","text":"O setare pentru cât de aventuroase sunt răspunsurile unui AI. O valoare mică dă răspunsuri mai stabile și mai previzibile; una mare, mai variate. Niciuna nu-l face să aibă mereu dreptate.","also":["temperatura","temperature","model temperature"],"noTip":1},{"id":"multimodal","g":"ai","word":"Multimodal","text":"Capabil să lucreze cu mai multe feluri de informații, de exemplu text, imagini și sunet.","also":["multi-modal","multimodal"]},{"id":"evals","g":"ai","word":"Evaluare (eval)","text":"Un test planificat care arată cât de bine se descurcă un AI pe exemple alese, ca să poți compara modele sau prompturi.","also":["eval","evals","evaluări"]},{"id":"bias","g":"ai","word":"Părtinire","text":"Când un AI (sau un om) înclină nedrept într-o parte, adesea din cauza datelor din care a învățat.","also":["prejudecată","părtinitor","bias","biased"],"noTip":1},{"id":"responsible","g":"ai","word":"AI responsabil","text":"Folosirea AI într-un mod corect, sigur și onest, cu oameni care răspund în continuare de rezultate.","also":["AI etic","responsible AI","ethical AI"]},{"id":"injection","g":"ai","word":"Prompt injection","text":"Un truc în care instrucțiuni ascunse într-o pagină web sau într-un fișier încearcă să determine un AI să facă ceva ce utilizatorul lui n-a cerut.","also":["injecție de prompt","prompt injections"]},{"id":"ratelimit","g":"ai","word":"Limită de cereri","text":"O limită pentru numărul de cereri pe care le poți trimite unui serviciu într-un interval stabilit. Dacă o depășești, trebuie să aștepți.","also":["limite de cereri","rate limit","rate limits","rate limited"]},{"id":"usagelimit","g":"ai","word":"Limită de utilizare","text":"Cât de multă muncă AI permite planul tău într-o perioadă, după care se oprește sau costă mai mult.","also":["limite de utilizare","usage limit","usage limits"]},{"id":"vibe","g":"ai","word":"Vibe coding","text":"A construi software mai ales descriindu-i unui AI ce vrei și lăsându-l să scrie codul.","also":["vibe-coding","programare pe vibe"]},{"id":"budget","g":"money","word":"Buget","text":"Suma de bani pusă deoparte pentru ceva.","also":["bugete","bugetul","budget"],"noTip":1},{"id":"costest","g":"money","word":"Estimare de cost","text":"O apreciere cât mai bună a cât va costa ceva, făcută înainte să începi.","also":["estimări de cost","cost estimate"]},{"id":"roi","g":"money","word":"Rentabilitatea investiției (ROI)","text":"Ce primești înapoi față de ce ai pus. Dacă e pozitiv, a meritat.","also":["ROI","return on investment","randament"]},{"id":"tco","g":"money","word":"Costul total de proprietate (TCO)","text":"Tot ce costă cu adevărat ceva pe toată durata de viață, nu doar prețul de cumpărare: rulare, suport, upgrade-uri și, la urmă, scoaterea din uz.","also":["TCO","total cost of ownership","cost total de deținere"]},{"id":"capex","g":"money","word":"CapEx și OpEx","text":"CapEx sunt banii cheltuiți dinainte pe lucruri pe care le păstrezi; OpEx sunt cheltuielile curente, de exemplu facturile lunare.","also":["CapEx","OpEx","cheltuieli de capital","cheltuieli operaționale","capital expenditure","operating expenditure"]},{"id":"subscription","g":"money","word":"Abonament","text":"A plăti regulat, de obicei lunar sau anual, ca să folosești în continuare ceva.","also":["abonamente","abonamentul","subscription"],"noTip":1},{"id":"saas","g":"money","word":"Software ca serviciu (SaaS)","text":"Software pe care îl folosești online și îl plătești prin abonament, în timp ce producătorul îl rulează pentru tine.","also":["SaaS","software as a service"]},{"id":"payg","g":"money","word":"Plată în funcție de utilizare","text":"A plăti doar ce folosești, ca la cloud sau la tokenii AI.","also":["plată pe măsură ce folosești","pay as you go","pay-as-you-go","usage-based pricing"]},{"id":"overage","g":"money","word":"Depășire","text":"Utilizare peste ce include planul tău, care poate costa în plus.","also":["depășiri","taxă de depășire","overage","overages","overage charges"]},{"id":"billingalert","g":"money","word":"Alertă de facturare","text":"Un mesaj când cheltuielile sau utilizarea ajung la un nivel ales de tine. Te avertizează, dar nu oprește mereu costurile ulterioare.","also":["alerte de facturare","billing alert","spending alert"]},{"id":"freetier","g":"money","word":"Nivel gratuit","text":"Un nivel gratuit al unui serviciu cu plată, cu limite. Util la început.","also":["plan gratuit","free tier","free plan"]},{"id":"pricing","g":"money","word":"Plan tarifar","text":"Pachetele diferite pe care le vinde un serviciu, fiecare cu prețul și limitele lui.","also":["planuri tarifare","pricing plan","price plan"]},{"id":"licence","g":"money","word":"Licență","text":"Regulile despre cum ai voie să folosești, să copiezi, să schimbi sau să distribui ceva făcut de altcineva, de exemplu software, fonturi sau imagini.","also":["licențe","licența","licence","license","licenses"],"noTip":1},{"id":"opensource","g":"money","word":"Open source","text":"Software al cărui cod îl poate citi, folosi și adesea schimba oricine, gratuit, după regulile licenței lui.","also":["cod sursă deschis","open-source","open source software","OSS"]},{"id":"osslicence","g":"money","word":"Licență open source","text":"Regulile care vin cu codul open source. Unele îți permit aproape orice (ca MIT); altele cer să-ți publici și tu schimbările (ca GPL).","also":["licențe open source","open source licence","licență MIT","MIT licence","GPL"]},{"id":"proprietary","g":"money","word":"Proprietar","text":"Deținut de o companie și nu liber de copiat sau de schimbat. Opusul lui open source.","also":["software proprietar","proprietary","proprietary software"]},{"id":"copyright","g":"money","word":"Drept de autor","text":"Dreptul legal al unui creator de a controla copiile operei sale, inclusiv codul și textele.","also":["drepturi de autor","copyright","copyrighted"],"noTip":1},{"id":"ip","g":"money","word":"Proprietate intelectuală (IP)","text":"Idei și creații pe care legea le tratează ca fiind deținute, de exemplu cod, designuri, nume și sigle.","also":["IP","intellectual property"]},{"id":"tos","g":"money","word":"Termeni și condiții","text":"Regulile pe care le accepți când folosești un serviciu.","also":["termeni de utilizare","condiții de utilizare","terms of service","terms and conditions","terms of use"]},{"id":"contract","g":"money","word":"Contract","text":"Un acord scris între două părți pe care legea îl susține.","also":["contracte","contractul","contract"],"noTip":1},{"id":"sow","g":"money","word":"Declarație de lucru (SOW)","text":"Un document care stabilește exact ce muncă se va face, până când și cu cât.","also":["SOW","statement of work","caiet de sarcini"]},{"id":"fixedprice","g":"money","word":"Preț fix","text":"Un preț convenit pentru toată lucrarea, oricât ar dura.","also":["preț fix","fixed price","fixed-price"]},{"id":"tm","g":"money","word":"Timp și materiale","text":"A plăti orele muncite cu adevărat și lucrurile folosite cu adevărat, nu un preț stabilit.","also":["T&M","time and materials","plată pe ore"]},{"id":"invoice","g":"money","word":"Factură","text":"O notă care cere plata pentru munca făcută sau bunurile furnizate.","also":["facturi","factura","invoice"],"noTip":1},{"id":"lockin","g":"money","word":"Dependență de furnizor","text":"Când schimbarea furnizorului e atât de grea sau de costisitoare încât ești legat de el.","also":["vendor lock-in","lock-in","blocare la furnizor"]},{"id":"procurement","g":"money","word":"Achiziții","text":"Procesul de alegere a furnizorilor și de cumpărare de la ei.","also":["achiziție","procurement"]},{"id":"servicecredit","g":"money","word":"Credit de serviciu","text":"Bani returnați sau o reducere pe care o primești când un furnizor nu respectă SLA-ul.","also":["credite de serviciu","service credit","service credits"]}]}};
